(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["eu"] = {"ui":{"skip":"Joan edukira","back":"← Itzuli AI-gilera","lang.button":"Hizkuntza: {name}","lang.dialog":"Aukeratu hizkuntza bat","lang.search":"Bilatu hizkuntzak","lang.none":"Ez dago hizkuntzarik bat datorrenik","lang.notYet":"{name} ez dago oraindik itzulita","theme.aria":"Aldatu gaia: argia, iluna edo beltza","theme.toLight":"Aldatu gai argira","theme.toDark":"Aldatu gai ilunera","theme.toBlack":"Aldatu gai beltzera (benetako beltza, OLED pantailentzat leuna)","words.underline":"Azpimarratu hitz hauek orrian","words.underlineHelp":"Pasatu sagua edo sakatu puntuz azpimarratutako hitz baten gainean, zer esan nahi duen ikusteko.","words.col.todo":"Oraingoz aukeratutako txartelak: taldea hauekin hasiko da hurrena.","words.col.doing":"AI bat lanean ari da txartel honetan orain.","words.col.review":"AI batek lana amaitu du; beste batek aztertzen du zuregana iritsi aurretik.","words.col.verify":"Zure zain: probatu eta esan funtzionatzen duen ala ez.","words.col.team":"Zure oharrak edo erantzunak, taldeak jaso arte zain.","words.col.done":"Amaituta eta onartuta.","index.title":"AI-gile: zure AI garapen-taldea, taula bakarrean","index.description":"AI-gile AA bidezko programazio-taldeentzako kanban taula bat da. Zu lo zaudela lan egiten dute; zuk pila labur bat jasotzen duzu, erabaki, probatu eta onartzeko gauzekin.","hero.logoAlt":"AI-gile taularen ikonoa","hero.h1.html":"Zure AI garapen-taldea, taula&nbsp;bakarrean.","hero.alpha":"🐣 Aurre-alfa itxia","hero.alphaTitle":"Goiztiarra eta bukatu gabea: eskerrik asko probatzeagatik!","hero.lede":"Zu lo zaudela eraikitzen dute. Esnatzean pila labur bat izango duzu zain: galdera batzuk, probatzeko gauza batzuk, diamante more bat edo bi. Klik egin, onartu, eta itzuli zure kafera.","dl.windows":"Windows aplikazioa","dl.browser":"Erabili nabigatzailean","dl.messenger":"📱 Messenger zure telefonorako","dl.soon":"Laster","dl.notify":"🔔 Abisatu irekitzen denean","dl.notifySmall":"Alfa edo beta","hero.secondary":"Agile, baina taldeak ez du inoiz zutik egindako bilerako kafearen beharrik. (Zutik egindako bilerak egiten dituzte, hala ere.)","pitch.h2":"AI-gile nahi adina hitzetan","pitch.lede":"Aukeratu luzera bat, hitz batetik 144ra. Luzera bakoitza bere deskribapena da, tamaina horretarako idatzia. Arrastatu graduatzailea edo erabili gezi-teklak.","pitch.rangeLabel":"Luzera hitzetan","pitch.dice":"🎲 beste bertsio bat","pitch.words.one":"{n} hitz","pitch.words.other":"{n} hitz","pitch.letters.one":"{n} letra","pitch.letters.other":"{n} letra","pitch.chars.one":"{n} karaktere","pitch.chars.other":"{n} karaktere","count.line.html.one":"{n} txartel taulan orain","count.line.html.other":"{n} txartel taulan orain","people.humans.html.one":"👥 {n} gizaki","people.humans.html.other":"👥 {n} gizaki","people.agents.html.one":"🤖 {n} agente","people.agents.html.other":"🤖 {n} agente","people.working.html.one":"⚡ {n} lanean une honetan","people.working.html.other":"⚡ {n} lanean une honetan","pre.title":"AI-gile: zerbait eraikitzen ari dira","pre.description":"Hemen zerbait eraikitzen ari dira. Taula bat, non AI taldeek eskatzen duzuna eraikitzen duten, bidean zuri irakatsiz. Oraingoz, lagunekin aurre-alfa itxia.","pre.h1":"Hemen zerbait eraikitzen ari dira. 🤫","pre.line":"Taula bat, non AI taldeek eskatzen duzuna eraikitzen duten, bidean zuri irakatsiz. Oraingoz, lagunekin aurre-alfa itxia.","pre.btn":"🔔 Abisatu irekitzen denean","pre.peek":"Kristalaren atzean: benetako taula, zuzenean. Txartel bakoitza koloretako barra bat da.","pre.peekFake":"Kristalaren atzean: hau da lanean ari den taula baten itxura.","pre.night":"🌙 Gaueko zaintzailea arduratzen da · 😴 gizakia atseden hartzen ari da","features.aria":"Zer egiten duen","f.pile.h":"Pila bakarra zuretzat","f.pile.html":"<b>Zuretzat</b> atalak zure zain dagoen guztia biltzen du, proiektu guztietatik: galderak, probatzeko gauzak, gizakiak bakarrik egin ditzakeen zereginak. Zure ilarak esaten dizu zer datorren eta zenbat denbora behar duen.","f.sleep.h":"Zu lo zaudela lan egiten duten taldeak","f.sleep.p":"Proiektu bakoitzak taldeburu bat eta AA agenteen talde bat ditu. Egin iruzkina txartel batean eta taldea esnatu egingo da, lana egin eta itzuliko dizu gizaki nekatu batek jarrai ditzakeen urratsekin.","f.tester.h":"AA probatzaile batek aurretik egiaztatzen du","f.tester.p":"Ezer zuregana iritsi aurretik, probatzaile batek aplikazioaren kopia batean urratsak jarraitzen ditu eta ikusi duena erakusten du, pantaila-argazkiarekin. Begiratu pasatakoak azkar eta onartu klik batekin.","f.proof.h":"Frogak, ez promesak","f.proof.p":"Entrega bakoitzak zer aldatu den erakusten du: fitxategiak, diff-a, pantaila-argazkiak. Ez duzu aplikazio bakoitza ireki behar bukatuta dagoen jakiteko.","f.chat.h":"Berriketan zure taldeburuekin","f.chat.p":"Discord estiloko barra bat: ikono bat proiektu bakoitzeko, diamante moreak zu behar zaituenarentzat. Bidali ideia bat taldeburuari; txartel eta plan bihurtuko du, ✅ Go botoiarekin.","f.tidy.h":"Bere burua txukun mantentzen du","f.tidy.p":"Elkarrekin lotutako txartelak bat egiten dute, titulu nahasiak zuzentzen dira, eta token-kontrolak kodea arin mantentzen du. Aldatzeko gauza gutxiago, pentsatzeko gutxiago.","f.private.h":"Zurea, zure ordenagailuan","f.private.li1":"Taula zure makinan exekutatzen da eta zuri bakarrik erantzuten dio.","f.private.li2":"Pertsonen arteko mezu pribatuak muturretik muturrera zifratuta daude.","f.private.li3":"Konturik gabe, aztarnaririk gabe, cookierik gabe.","f.lang.h":"Zure hizkuntzan","f.lang.p":"120 hizkuntza baino gehiago, nederlanderatik, galesetik eta japonieratik piratera, Yodara eta klingonera, termino teknikoetarako ingelesera itzultzeko aldaketa azkarrarekin.","f.service.h":"Ideia batetik benetako zerbitzu batera","f.service.p":"AIarekin jendeak orain erabiltzen duen zerbait eraiki duzu? Markatu zerbitzu gisa eta taulak ondo martxan izaten lagunduko dizu: erabilgarritasun-egiaztapenak, egoera-orri publikoa, txostena duten intzidenteak, Go bat behar duten aldaketak, egunero egiaztatutako babeskopiak. Laguntzak urrats bakoitza erakusten dizu bidean.","msgr.h2":"AI-gile Messenger: zure taldea poltsikoan","msgr.p1":"Hitz egin zure AI taldearekin taula ireki gabe. Txateatu zure proiektuburuekin eta lagunekin, eta ikusi txartel baten proba-urratsak eta erantzun, dena telefonotik.","msgr.p2":"Lotzeko, eskaneatu zure taulako QR kode bat. Lehen aldia? Demo-txat atsegin batek dena erakutsiko dizu.","msgr.when":"Lehenik Android, gero telefonoetarako eta iPhonerako web bertsio bat.","msgr.who":"Zure proiektuburua","msgr.b1":"Modu ilunaren konponketa prest dago. Proba-urratsak nahi dituzu?","msgr.b2":"Bai, mesedez!","msgr.b3":"1. Ireki Ezarpenak. 2. Aukeratu Iluna. Ondo ikusten da?","tl.aria":"Denbora-lerroa lehen elkarrizketatik ibilbide-orrira","tl.h2":"Lehen txatetik datorrenera","tl.lede":"Benetako datak eta orduak, zure ordu-zonan. Gaurtik aurrera plana da, daturik agindu gabe.","tl.today":"Gaur","tl.planned":"planifikatuta","tl.doing":"egiten","tl.cards.one":"{n} txartel","tl.cards.other":"{n} txartel","join.h2":"Egin bat","join.lede":"AI-gile AuDHDa eta buru-osasunarekin borroka batzuk dituen bizardun xelebre batek eta agente pazientzia handiko askok eraikitzen dute. Pribatua da oraingoz, lagunekin alfa itxian. Probatu nahiko zenuke irekitzen denean?","join.btn":"Eman interesa","join.small":"Posta elektronikoz idatziko dizugu, besterik ez","footer.tag":"AI-gile. Aztarnaririk gabe, cookierik gabe, zutik egindako bilerako kaferik gabe.","footer.licence":"Negozio-lizentzia","footer.status":"Egoera","footer.privacy":"Zer gordetzen dugun","footer.thanks":"Deiak ChilledChat-i esker","form.sending":"Bidaltzen…","form.failed":"Hori ez da ondo atera: saiatu berriro geroago.","form.offline":"Ezin izan da AI-gilerekin konektatu: saiatu berriro geroago.","form.keep":"Zuri erantzuteko bakarrik erabiltzen dugu, eta gero ezabatu egiten dugu. Aztarnaririk gabe, cookierik gabe.","form.keepLink":"Zer gordetzen dugun","interest.title":"AI-gile: abisatu alfa irekitzen denean","interest.description":"Utzi zure posta elektronikoa AI-gileren alfa edo beta itxia noiz irekitzen den jakiteko.","interest.h1":"🔔 Abisatu irekitzen denean","interest.lede":"AI-gile aurre-alfa itxian dago. Utzi zure posta elektronikoa eta behin idatziko dizugu, zuretzako lekua dagoenean.","interest.email":"Zure posta elektronikoa","interest.which":"Zein proba?","interest.alpha":"Alfa itxia: goiztiarra, latza, aldaketa asko","interest.beta":"Beta: egonkorragoa, geroagokoa","interest.both":"Edozein, zein lehenago ireki","interest.submit":"Jarri nazazu zerrendan","interest.thanks":"Eskerrik asko! Zerrendan zaude.","licence.title":"AI-gile: negozio-lizentzia","licence.description":"Erabiltzen al duzu AI-gile zure negozioan? Eskatu negozio-lizentzia doakoa.","licence.h1":"📜 Negozio-lizentzia","licence.lede":"Lanean erabiltzen al duzu AI-gile? Esan zeintzuk zareten eta zer egiten duzuen. Onik egiten badu, lizentzia doakoa da.","licence.company":"Enpresa","licence.website":"Webgunea","licence.what":"Zer egiten duzuen","licence.how":"Nola laguntzen dion munduari","licence.email":"Posta elektronikoa","licence.submit":"Eskatu","licence.thanks":"Eskerrik asko! Posta elektronikoz erantzungo dizugu.","status.title":"AI-gile egoera","status.h1":"AI-gile egoera","status.quiet":"Dena lasai","status.intro":"AI-gile badabil orain? Orri honek 5 minuturo egiaztatzen ditu webgunea, taulak partekatzea, deiak eta deskarga.","status.up":"Badabil ({ms} ms-tan erantzun du)","status.slow":"Ez dio azken egiaztapenari erantzun, berriro saiatzen","status.down":"Erorita: ez die azken bi egiaztapenei erantzun","status.svc.web":"Webgunea","status.svc.web.offers":"Gune hau: zer den AI-gile, eta interes-formularioa","status.svc.boards":"Taulak partekatzea","status.svc.boards.offers":"Taula publikoak, lagunen arteko mezuak eta gonbidapenak","status.svc.calls":"Deiak","status.svc.calls.offers":"Ahotsa, bideoa eta pantaila partekatzea AI-gile-n","status.svc.download":"Deskarga","status.svc.download.offers":"Windowserako instalatzailea eta gonbidapen-estekak","status.checking":"Egiaztatzen…","status.offline":"Ezin da egoera-zerbitzura heldu orain (berriro saiatzen)","status.updated":"eguneratua {ago}","status.justNow":"orain bertan","status.min":"duela {n} min","status.hours":"duela {n} h","status.days":"duela {n} egun","privacy.title":"AI-gile: zer gordetzen dugun","privacy.h1":"Zer gordetzen dugun","privacy.lede":"Laburbilduz: bidaltzen diguzuna bakarrik, eta ez denbora luzez.","privacy.only":"Bidaltzen diguzuna bakarrik: formulario batean idazten duzuna, zure posta elektronikoa adibidez. Zuri buruzko beste ezer ez.","privacy.sealed":"Zigilatu egiten da, gure zerbitzariak irakurri ez dezan: zure nabigatzailean, irten aurretik (nabigatzaile zaharrago batean, iristen den unean). Gure taulak bakarrik ireki dezake.","privacy.server":"Zerbitzaritik ezabatzen da gure taulara iritsi bezain laster. 30 egunen ondoren oraindik han dagoena ere ezabatu egiten da, hala ere.","privacy.board":"Gure taulan gordetzen dugu zuri erantzun arte bakarrik, eta gero handik ere ezabatzen dugu.","privacy.none":"Aztarnaririk gabe, cookierik gabe, analitikarik gabe.","privacy.local":"Zure hizkuntza eta modu argiaren edo ilunaren aukera zure nabigatzailean bertan geratzen dira. Ez zaizkigu inoiz bidaltzen.","privacy.ask":"Lehenago ezabatzea nahi duzu? Erantzun gure mezu elektronikoari eta esaiguzu.","live.h2":"Ikusi nola eraikitzen den, zuzenean","live.caption":"Txartel guztiak ezkutuan daude: lanaren forma ikusten duzu, ez hitzak.","live.watching.one":"zuzenean: {n} ikusten","live.watching.other":"zuzenean: {n} ikusten","live.last.now":"Azken txartela orain bertan mugitu da","live.last.min.one":"Azken txartela duela {n} min mugitu da","live.last.min.other":"Azken txartela duela {n} min mugitu da","live.last.hour.one":"Azken txartela duela {n} ordu mugitu da","live.last.hour.other":"Azken txartela duela {n} ordu mugitu da","live.last.day.one":"Azken txartela duela {n} egun mugitu da","live.last.day.other":"Azken txartela duela {n} egun mugitu da","live.offline":"Zuzeneko taulak atsedentxo bat hartzen ari da. Itzuli laster.","live.cols":"Backlog|Egiteko|Egiten|Taldeak aztertzen|Zuk probatzeko|Taldearentzat|Eginda","footer.models":"AI-gile zuretzat IA ereduak exekutatzeko tresna da. Haiek esaten eta egiten dutena haiena da, beraz egiaztatu fidatu aurretik.","privacy.ai.h":"IAren zatia","privacy.ai.models":"AI-gile taula da. Lana beste enpresa batzuen IA ereduek egiten dute, Claude, Codex eta Gemini bezalakoek, zure kontuetan.","privacy.ai.check":"Haiek idazten eta egiten dutena haiengandik dator eta okerra izan daiteke. Egiaztatu horretan oinarritu edo argitaratu aurretik.","privacy.ai.files":"Fitxategiak aldatzen dituzte eta komandoak exekutatzen dituzte konektatzen dituzun karpetetan. Egin babeskopia bat.","privacy.ai.send":"Eredu bati ematen diozuna hura exekutatzen duen enpresara doa, haren baldintzen arabera. Bakoitzaren baldintzak eta kostuak aplikatzen dira.","privacy.ai.asis":"AI-gile hasierako proba-bertsio bat da, dagoen bezala emana."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotak.","Delegatuta."]},{"n":2,"texts":["Robotak lanean.","Agenteak, antolatuta.","Ideiak, eraikita."]},{"n":3,"texts":["Kanbana robotentzat.","Ideiak ezaugarri bihurtzen.","Agente-kanban doakoa."]},{"n":5,"texts":["Agenteek zuzendutako kanban taula.","Zuk idatzi, agenteek eraiki.","Doakoa, lokala, probatua, apur bat zentzugabea."]},{"n":8,"texts":["AA agenteek lan egiten duten kanban taula doakoa.","Idatzi ideia bat. Agenteek eraikiko dute. Zuk onartu.","Agile gizaki batentzat eta robot pazientzia handiko askorentzat."]},{"n":13,"texts":["Zure ordenagailuko kanban taula, non AA agenteek txartelak hartzen eta lana egiten duten.","Idatzi ideia bat. Agenteen talde batek eraikiko du. Probatzaile batek egiaztatuko du.","Doakoa, konturik gabe, aztarnaririk gabe: taula bat, robot batzuk, eta zu agintean."]},{"n":21,"texts":["AI-gile AA bidezko programazio-agenteekin lan egiteko kanban taula bat da. Haiek hartzen dituzte txartelak; zuk probatu eta onartzen dituzu.","Proiektu bakoitzak taldeburu bat eta AA agenteen talde bat izaten ditu. Egin iruzkina edozein txartelean eta taldea lanean hasiko da.","Zure ordenagailuan exekutatzen den zeregin-taula pertsonal eta doakoa, konturik eta aztarnarik gabekoa. Langileak robotak dira. Baiezkoa ematen duena zu zara."]},{"n":34,"texts":["Ideiak taulan jartzen dituzu. AA agenteen talde batek ezaugarri funtzionaletan bihurtzen ditu, probatu egiten ditu eta probatzeko urratsekin itzultzen dizkizu. Ezer ez da bukatutzat jotzen zuk esan arte.","AI-gile etxean egindako kanban taula bat da, Richek eraiki zuena orain kudeatzen dituen agenteen laguntza handiarekin. Doakoa da, zure ordenagailuan exekutatzen da eta lagunekin partekatzen da, ez saltzen.","Imajinatu ohiko kanban taula bat, Backlogetik Eginda arteko zutabeekin, baina txartelak AA agenteek hartzen dituztela. Aurrerapenaren berri ematen dute, galdetzen dute trabatuta daudenean, eta beti zure baiezkoaren zain geratzen dira."]},{"n":55,"texts":["AI-gile kanban taula bat da, eta bertako taldea AA agenteek osatzen dute. Proiektu bakoitzak lana planifikatzen duen taldeburu bat eta eraikitzen duten laguntzaile batzuk ditu. Ezaugarri bat prest dagoenean, AA probatzaile batek probatu eta pantaila-argazkia ateratzen du, eta gero zure pilara iristen da. Onartu, edo egin iruzkina eta berriro lantzen dute.","Pertsona baten modua izan zen aldi berean AA bidezko programazio-saio asko jarraitzeko, eta benetako taula bihurtu zen. Zure makinan exekutatzen da, ez du konturik behar eta ez dauka aztarnaririk. Doakoa da lagunentzat eta jakin-minez daudenentzat. Bukatu gabe ere badago, beraz espero ertz latz batzuk eta noizbehinkako sorpresaren bat.","Hau da bertsio zintzoa. Zuk bururatu behar dituzu oraindik ideiak, eta zuk egiaztatu behar dituzu emaitzak. AI-gilek tartean dagoen guztia egiten du: txartelak ordenean mantentzen ditu, agente egokia esnatzen du iruzkina egitean, zehazki zer aldatu den erakusten du, eta dena pila labur batean uzten du zuretzat."]},{"n":89,"texts":["AI-gile zure ordenagailuan exekutatzen duzun kanban taula doakoa da. Pertsonen ordez, proiektu bakoitzak AA agenteen talde bat du: zure ideiak txartel eta plan bihurtzen dituen taldeburu bat, eta txartelak lehentasun-ordenan hartzen dituzten laguntzaileak. Zerbait eraikita dagoenean, AA probatzaile batek proba-urratsak jarraitzen ditu eta ikusi duena erakusten dizu. Gero Zuretzat izeneko pila batean geratzen da zain. Onartzen duzu, edo iruzkina egiten duzu eta taldeak berriro saiatzen da. Ezer ez da inoiz Eginda zutabera iristen zu gabe.","Ez dituzun espero agian gauza batzuk. Gaueko zaintzak Egiteko zutabea beteta mantentzen du zu lo zaudela, zure erantzunik behar ez duten txartelak aukeratuz. Token-kontagailuak erakusten du agenteek gaur eta aste honetan zenbat erabili duten, eta Token-gabeko Moduak gastatzeari uzteko esaten die. Lagunei mezuak bidal diezazkiezu, eta mezu pribatuak muturretik muturrera zifratuta daude. Taulak 120 hizkuntza inguru hitz egiten ditu, nederlandera, flandestarra, pirata eta klingonera barne. Horietako ezerk ez du zentimorik balio, eta inork ez dizu saltzen saiatzen ere.","AI-gile proiektu txiki eta pertsonala da, ez enpresa bat. Richek AA bidezko programazio-proiektu batzuk zaindu nahi zituen aplikazio bakoitza irekitzeke zer moduz zeuden begiratzeko, beraz berak eta agenteek horretarako taula bat eraiki zuten, eta gero taula bera erabili zuten gainerakoa eraikitzeko. Aurre-alfa itxian dago, hau da, funtzionatzen du, gehienetan, lagun sorta txiki batentzat. Ez dago prezio-orririk, ez albisteak bidaltzen dituenik eta ez hazkunde-planik. Erabilgarria iruditzen bazaizu, probatzeko eskatu dezakezu apur bat gehiago irekitzen denean."]},{"n":144,"texts":["AI-gile gizaki bakar batentzako eta AA agente askorentzako kanban taula bat da. Zure ordenagailuan exekutatzen da eta guztiz doakoa da. Proiektuak gehitzen dituzu, eta proiektu bakoitzak taldeburu bat eta talde txiki bat izaten ditu. Taldeburuarekin berriketan aritzen zara, Discorden antzera, eta ideia bat deskribatzen duzu; taldeburuak txartel eta plan bihurtzen du, eta Go sakatzeko zain geratzen da. Taldeak txartelak lehentasun-ordenan egiten ditu, hizkuntza-ereduentzat egindako komando-lerro sinple bat erabiliz. Ezer zuregana itzuli aurretik, AA probatzaile batek aplikazioaren kopia batean urratsak jarraitzen ditu eta pantaila-argazki bat eransten du. Amaitutako lana zure pilara iristen da, aldatutako fitxategiekin eta diff-arekin. Onartzen duzu, edo iruzkin bat uzten duzu eta taldea esnatu eta berriro saiatzen da. Zuk bakarrik mugi dezakezu txartel bat Eginda zutabera.","AI-gilerekin egun bat, gutxi gorabehera. Arratsaldean iruzkin batzuk uzten dituzu: botoi hau toki okerrean dago, zerrenda hori ordenatu beharko litzateke, modu iluna izan genezake. Ohera zoaz. Agenteek iruzkinak irakurtzen dituzte, aldaketak egiten dituzte, probatzen dituzte eta itzultzen dizkizute. Egiteko zutabea hustuz gero, gaueko zaintzak backlogetik betetzen du, zure erantzunik behar ez duten txartelekin. Goizean pila labur bat dago: galdera pare bat eta probatzeko gauza batzuk, bakoitza lo gaizto dagoen pertsona batek jarrai ditzakeen urratsekin eta funtzionatzen duela erakusten duen pantaila-argazkiarekin. Klik eginez igarotzen zara, onak onartzen dituzu eta gainerakoak itzultzen dituzu. Token-kontagailuak erakusten du horrek guztiak zer erabili duen, eta Token-gabeko Modua aste mehe horietarako dago. Gero gosaltzen duzu, agenteek oraindik laguntzen ezin dutena. Kafea, berriz, lasai edan dezakezu.","Lehenik, zer ez den AI-gile. Ez da startup bat, ez dago salgai, eta inork ez ditu zure datuak biltzen. Zure ordenagailuan exekutatzen den taula doakoa da, konturik gabe, aztarnaririk gabe eta cookierik gabe. Zer den: AA bidezko programazio-proiektu guztiak aldi berean ikusteko leku txukun bat, agente-talde batek txartelak egiten dituela eta zuk erabakiak hartzen dituzula. Lotutako txartelak batzen ditu, titulu nahasiak zuzentzen ditu, eta kodea zein arin mantentzen den zaintzen du. 120 hizkuntza inguru hitz egiten ditu, nederlandera eta flandestarretik pirata eta klingonera. Lagunek elkarri mezuak bidal diezazkiokete, pribatuki eta zifratuta. Richek eta agente pazientzia handiko askok eraiki zuten, gehienbat bera bera erabiliz. Aurre-alfa itxian dago, beraz toki batzuetan latza da. Dibertigarria dirudiela uste baduzu, eskatu ondo eta agian goiz sartuko zara."]}],"quips":{"1":"Hitz bat. Ausarta. Agian gehiegi.","3":"Hiru hitz. Produktu-orri gehienak baino zintzoagoa jada.","8":"Zortzi hitz. Zutik egindako bilera bat baino laburragoa oraindik.","21":"Luzerak story point-ak dira, bide batez. Noski baietz.","55":"Berrogeita hamabost hitz. Bi txartel bukatu dira hau irakurtzen ari zinen bitartean.","144":"Hori da luzea. Ez dago 233rik. Agenteak ohera joan dira."}},"timeline":{"first-idea.name":"Lehen ideia","first-idea.line":"Lehen elkarrizketa, kodeik existitu aurretik.","first-board.name":"Lehen taula","first-board.line":"Bere eraikuntza bera jarraitzen duen taula: txartelak, zutabeak, arrastatu eta jaregin, proiektuak.","team-roles.name":"Taldea eta rolak","team-roles.line":"Agente-profilak, talde-txantiloiak, guneak eta nork zer egiten duen.","install.name":"Instalazioa eta bertsioak","install.line":"Lagun batek instala dezakeen zip bat, auto-eguneraketak, kanalak eta atzera egitea.","usage-saver.name":"Erabilera-aurrezlea","usage-saver.line":"Neurtu zenbat kostatzen diren exekuzioak, mantendu kodea arin, aurreztu zure muga.","friends.name":"Lagunak eta partekatzea","friends.line":"Mezu pribatuak, errele nahastua, gonbidapenak, rolak eta proiektu partekatuak.","languages.name":"Hizkuntzak","languages.line":"Pantailako testu guztiak hizkuntza-fitxategi batean, nederlandera eta flandestarra lehenengo.","ai-tester.name":"AA probatzailea","ai-tester.line":"Probatzaile batek entrega bakoitza aurretik egiaztatzen du eta ikusi duena erakusten du.","website.name":"Webgunea","website.line":"aigile.lol, teaser-a eta denbora-lerro hau.","streaming.name":"Txata eta streaming-a","streaming.line":"Discord, Twitch, OBS, streamer modua, GIFak eta emojiak.","no-ai.name":"AArik gabeko edizioa","no-ai.line":"AArik gabe programatzen dutenentzako taula, eta taula publikoak.","night-watch.name":"Gaueko zaintza","night-watch.line":"Zaindari batek eta Scrum Master batek taldeak zereginean mantentzen dituzte zu lo zaudela.","p-more.name":"Gainerako guztia","p-more.line":"Oraindik txandaren zain dauden ideia txikiagoak.","p-android.name":"Telefonoa eta Android","p-android.line":"Iritsi zure taulara telefonotik, gero Android aplikazio natibo batera.","p-release.name":"Alfa eta haratago","p-release.line":"Alfa itxia, webgune bizia, gero beta.","p-languages.name":"Hizkuntza gehiago","p-languages.line":"130 hizkuntza, eta murgiltze modu bat ikasten ari direnentzat.","p-engines.name":"AA motor gehiago","p-engines.line":"Aukeratu Claude, Codex, Gemini, Copilot edo Cursor agente bakoitzeko.","p-pro.name":"Praktika profesionala","p-pro.line":"Arrisku-etiketak, bateratze-ateak, intzidentzia-txartelak eta babes-hesiak.","p-self.name":"Zure zaintza","p-self.line":"Nekatuta modua, norberaren zaintzarako gogorarazpenak eta 4:20.","p-servers.name":"Zerbitzariak eta eskala","p-servers.line":"Zerbitzari-ezarpen orokorrak, rolak eta hazkundea planifikatzea.","p-livestream.name":"Streaming-aren gehigarriak","p-livestream.line":"Twitch txata, emoji pertsonalizatuak eta zuzeneko ikuspegi publikoa."},"words":{"button":"📖 Termino teknikoak","h":"📖 Hitzak azalduta","intro":"Doako prestakuntza hizkera argian: lehen ideiatik jendeak behar duen zerbitzura aurkituko dituzun hitz guztiak, Agile, eraikuntza, segurtasuna eta AIarekin lan egitea barne.","search":"Bilatu hitz bat…","none":"Ez dago horrekin bat datorren hitzik.","close":"Itxi","count":{"one":"{count} hitz","other":"{count} hitz"},"groups":[{"id":"idea","name":"💡 Ideia eta esplorazioa"},{"id":"plan","name":"🗺️ Lana planifikatzea"},{"id":"agile","name":"🔁 Lan egiteko modu arinak"},{"id":"build","name":"🛠️ Eraikitzea"},{"id":"test","name":"🧪 Probak eta kalitatea"},{"id":"change","name":"🔀 Seguru aldatzea"},{"id":"run","name":"🛎️ Zerbitzu bat martxan izatea"},{"id":"sec","name":"🔒 Segurtasuna eta pribatutasuna"},{"id":"ai","name":"🤖 AIarekin lan egitea"},{"id":"money","name":"💰 Dirua eta lizentziak"}],"list":[{"id":"discovery","g":"idea","word":"Esplorazioa","text":"Ezer eraiki aurretik, zein arazo konpontzea merezi duen eta norentzat aztertzeko hasierako etapa.","also":["esplorazio fasea","discovery","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Arazoaren azalpena","text":"Nork zer arazo duen eta zergatik den garrantzitsua azaltzen duten esaldi bat edo bi, denek helburu bera izan dezaten.","also":["arazoen azalpenak","problem statements"]},{"id":"user","g":"idea","word":"Erabiltzailea","text":"Egiten duzuna erabiltzen duen pertsona. Haren beharrak asetzeko egiten da lana.","also":["erabiltzaileak","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Interesduna","text":"Emaitzan interesa duen edo haren eragina jasotzen duen edonor: ordaintzen, erabiltzen edo laguntza ematen dutenak, adibidez.","also":["interesdunak","stakeholders"]},{"id":"persona","g":"idea","word":"Erabiltzaile eredua","text":"Erabiltzaile mota bat ordezkatzen duen pertsona asmatu baina sinesgarria, taldeak «Samentzat erraza litzateke?» galdetu ahal izateko.","also":["erabiltzaile ereduak","personas"]},{"id":"userresearch","g":"idea","word":"Erabiltzaile ikerketa","text":"Benetako pertsonekin hitz egin eta haiek behatzea, zer behar duten ikasteko, asmatu beharrean.","also":["erabiltzaile elkarrizketak","user research","user interviews"]},{"id":"journey","g":"idea","word":"Erabiltzailearen ibilbidea","text":"Zerbait lortzeko pertsonak egiten dituen urratsak, lehen aldiz entzuten duenetik amaitu arte, produktutik kanpo ere bai. Marrazteak non trabatzen den erakusten du.","also":["erabiltzaile ibilbideak","customer journey","user journey","user journeys"]},{"id":"painpoint","g":"idea","word":"Eragozpena","text":"Gaur egun jendea gogaitzen edo moteltzen duen zerbait. Produktu onek eragozpen horiek kentzen dituzte.","also":["eragozpenak","pain points"]},{"id":"assumption","g":"idea","word":"Ustea","text":"Egiaztatu gabe sinesten duzun zerbait. Usteak idazteak zer probatu lehenik erakusten du.","also":["usteak","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hipotesia","text":"Egiaztatu nahi duzun ustea eta espero duzun emaitza, adibidez «lehen hilabetea doan bada, jendeak izena emango du».","also":["hipotesiak","hypotheses"]},{"id":"experiment","g":"idea","word":"Esperimentua","text":"Ideia batek funtzionatzen duen ikasteko proba txiki planifikatua, asko arriskatu aurretik.","also":["esperimentuak","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Kontzeptu proba (PoC)","text":"Ideia bat bideragarria den ikusteko saiakera azkar eta zakarra. Erantzuna lortutakoan, normalean baztertu egiten da.","also":["PoC","kontzeptu proba","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototipoa","text":"Produktuaren hasierako eredua, sarritan sakatu daitezkeen irudiz egina, ondo eraiki aurretik jendearekin probatzeko.","also":["prototipoak","prototypes"]},{"id":"wireframe","g":"idea","word":"Pantailaren zirriborroa","text":"Gauza bakoitza non joango den erakusten duen pantaila marrazki erraza, kolorerik eta benetako edukirik gabe.","also":["pantaila zirriborroak","wireframes"]},{"id":"mockup","g":"idea","word":"Maketa","text":"Pantailak izango duen itxuraren irudi zehatza, benetako kolore eta testuekin, baina oraindik funtzionatu gabe.","also":["maketak","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Proiektuaren justifikazioa","text":"Proiektu bat egiteko arrazoiak: kostua, ekarriko duen irabazia edo aurrezkia eta arriskuak.","also":["proiektuen justifikazioak","business cases"]},{"id":"feasibility","g":"idea","word":"Bideragarritasuna","text":"Eskura dituzun denbora, diru eta ezagutzekin zerbait benetan eraiki eta zaindu daitekeen.","also":["bideragarria","feasibility"]},{"id":"outcome","g":"idea","word":"Emaitza","text":"Pertsonentzat lortu nahi duzun aldaketa, adibidez hitzordu gutxiago galtzea. Zenbat eraikitzen duzun baino garrantzitsuagoa da.","also":["emaitzak","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Ekoitzitakoa","text":"Taldeak egiten duen zerbait, pantaila berri bat edo txosten bat adibidez. Egiteak ez du berez esan nahi inori laguntzen dionik.","also":["ekoizpenak","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Arrakasta adierazlea","text":"Lanak helburua bete duen erakusten duen zenbakia, adibidez eskaera amaitzen duten pertsona gehiago izatea.","also":["arrakasta adierazleak","success metrics"]},{"id":"kpi","g":"idea","word":"Errendimendu adierazle nagusia (KPI)","text":"Gauzak ondo doazen jakiteko jarraitzen duzun zenbaki garrantzitsua, adibidez asteko izen emateak.","also":["KPI","KPIs","errendimendu adierazle nagusia","key performance indicator"]},{"id":"okr","g":"idea","word":"Helburuak eta emaitza nagusiak (OKR)","text":"Helburuak ezartzeko modu bat: helburuak zer nahi duzun dio, eta emaitza nagusiek hori lortu duzula erakusten duten zenbakiak ematen dituzte.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Produktua","text":"Erabiltzaileentzat eraiki eta zaintzen den gauza, app bat, webgune bat edo tresna bat adibidez.","also":["produktuak","products"],"noTip":1},{"id":"vision","g":"plan","word":"Produktuaren ikuspegia","text":"Produktuak nori laguntzen dion eta epe luzera nora doan azaltzen duen adierazpen laburra.","also":["ikuspegiaren adierazpena","vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"Zer eraiki eta zer ordenatan erabakitzen duen pertsona, taldeak garrantzitsuena lehenik egin dezan. AI-gilen zu zara.","also":["PO","product owners","produktuaren arduraduna"]},{"id":"pm","g":"plan","word":"Produktu kudeatzailea (PM)","text":"Produktuaren norabidea zaintzen duen pertsona: zein arazo konpontzen dituen, norentzat eta zergatik. PM proiektu kudeatzailea ere izan daiteke; egiaztatu esanahia.","also":["produktu kudeatzaileak","product managers"]},{"id":"projmgr","g":"plan","word":"Proiektu kudeatzailea","text":"Proiektua garaiz eta aurrekontuaren barruan mantentzen duen pertsona, nork zer eta noizko egiten duen jarraituz.","also":["proiektu kudeatzaileak","project managers"]},{"id":"roadmap","g":"plan","word":"Bide orria","text":"Datozen hilabeteetan zer egingo den, ordenan, erakusten duen gutxi gorabeherako plana. Norabidea erakusten du, ez data zehatzak, eta ikasi ahala aldatzen da.","also":["bide orriak","roadmaps"]},{"id":"milestone","g":"plan","word":"Mugarria","text":"Proiektuan nabarmentzea merezi duen unea, adibidez «lehen bertsioa argitaratuta» edo «100 erabiltzaile».","also":["mugarriak","milestones"]},{"id":"mvp","g":"plan","word":"Gutxieneko produktu bideragarria (MVP)","text":"Benetako pertsonentzat erabilgarria den produktuaren bertsiorik txikiena, haiengandik goiz ikasteko.","also":["MVP","MVPs","gutxieneko produktu bideragarria","minimum viable product"]},{"id":"requirement","g":"plan","word":"Eskakizuna","text":"Amaitutako produktuak egin edo bete behar duen zerbait.","also":["eskakizunak","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Irismena","text":"Lanaren barruan zer sartzen den eta, bezain garrantzitsua, zer geratzen den kanpoan.","also":["irismenaren barruan","irismenetik kanpo","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Irismenaren kontrolik gabeko hazkundea","text":"Lanari pixkanaka gero eta gauza gehiago gehitzea, denbora edo kostu gehigarria adostu gabe, lana inoiz ez amaitzeraino.","also":["scope creep","feature creep"]},{"id":"feature","g":"plan","word":"Funtzionaltasuna","text":"Produktuarekin egin daitekeen gauza bat, adibidez «pasahitza berrezarri».","also":["funtzionaltasunak","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epika","text":"Aldi bakarrean egiteko handiegia den lana; txartel txikiagotan banatzen da.","also":["epikak","epics"]},{"id":"story","g":"plan","word":"Erabiltzaile istorioa","text":"Erabiltzailearen ikuspegitik idatzitako lan txikia: «Erosle gisa, saskia gorde nahi dut gero amaitzeko». Zer eraiki behar den hitz egiten hasteko balio du.","also":["erabiltzaile istorioak","user stories"]},{"id":"ac","g":"plan","word":"Onarpen irizpideak (AC)","text":"Txartela amaitutzat emateko bete beharreko baldintzak, lanean hasi aurretik adostuak; adibidez, saioa itxi eta berriro irekitzean saskiak hor jarraitzea.","also":["onarpen irizpideak","acceptance criteria"]},{"id":"task","g":"plan","word":"Zeregina","text":"Egin beharreko lan bakarra, sarritan istorio handiago baten urrats txikia.","also":["zereginak","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Tiketa","text":"Txartela esateko beste modu bat: hasieratik amaierara jarraitzen den lan edo eskaera bat.","also":["tiketak","tickets"]},{"id":"priority","g":"plan","word":"Lehentasuna","text":"Zerbaitek besteen aldean duen garrantzia edo presa, garrantzitsuena lehenik egiteko.","also":["lehentasunak","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Lehentasunak ezartzea","text":"Lana garrantziaren arabera ordenatzea. Modu ezagun bat MoSCoW da (Must, Should, Could, Won’t): ezinbestekoa, komenigarria, aukerakoa eta oraingoan egingo ez dena.","also":["lehenetsi","MoSCoW","prioritisation"]},{"id":"estimate","g":"plan","word":"Zenbatespena","text":"Lanaren tamainaren edo iraupenaren kalkulu hurbildua. Uste bat da, ez hitzemate bat.","also":["zenbatespenak","estimation","estimates"],"noTip":1},{"id":"storypoints","g":"plan","word":"Istorio puntuak","text":"Lanaren tamaina orduetan kalkulatu beharrean, txartelak elkarren artean alderatuz kalkulatzeko modua, adibidez «hura baino bi aldiz handiagoa». Ez dira taldeak alderatzeko.","also":["istorio puntua","story points","story point"]},{"id":"tshirt","g":"plan","word":"Neurrien bidezko zenbatespena","text":"Lana S, M, L edo XL neurriekin kalkulatzea. Azkarra eta nahikoa da hasierako planetarako.","also":["kamiseta neurriak","t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Kalkulatzeko jolasa: denek tamaina txartela batera erakusten dute, eta handiena eta txikiena aukeratu dituztenek zergatia azaltzen dute.","also":["planifikazio pokerra","Scrum poker"]},{"id":"dependency","g":"plan","word":"Mendekotasuna","text":"Lan bat beste baten mende egotea, hura egin arte ezin delako hasi edo amaitu.","also":["mendekotasunak","dependencies"]},{"id":"blocker","g":"plan","word":"Oztopoa","text":"Orain lana aurrera eramatea eragozten duen edozer, erantzun falta edo tresna hondatua adibidez.","also":["oztopoak","blockers"]},{"id":"deadline","g":"plan","word":"Azken eguna","text":"Zerbait amaituta egon behar den eguna.","also":["azken egunak","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Entregagaia","text":"Lanak sortu eta entregatzen duen zerbait zehatza, funtzionatzen duen orri bat edo txosten bat adibidez.","also":["entregagaiak","deliverables"]},{"id":"forecast","g":"plan","word":"Aurreikuspena","text":"Orain dakizunaren arabera ziurrenik gertatuko denaren iragarpena, lana noiz amaituko den adibidez.","also":["aurreikuspenak","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Neurria","text":"Denboran neurtu eta jarraitzen duzun zerbait, bisitak edo konponketa baten iraupena adibidez.","also":["neurriak","metrics"]},{"id":"feedback","g":"plan","word":"Iritziak","text":"Jendeak zure lanari buruz esaten duen ona eta txarra. Goiz eta maiz jasotzea funtsezkoa da Agilen.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Oraindik planifikatu gabeko ideia eta lanen itxaron zerrenda, garrantzitsuena goian. Ez zaie heltzen Egiteko zutabera pasatu arte."},{"id":"sprint","g":"agile","word":"Sprint","text":"Lan aldi labur eta finkoa, sarritan astebete edo bikoa eta inoiz ez hilabetetik gorakoa, helburu batekin eta amaitzeko adostutako txartelekin.","also":["sprintak","sprint-ak"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Eguneroko bilera laburra: bakoitzak zer egin duen, gero zer egingo duen eta zerk oztopatzen duen. Scrumen daily scrum esaten zaio.","also":["standup","stand-ups","eguneroko bilera","daily scrum","daily stand-up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Txartelak taulako zutabeetan mugituz lan egitea, Egiteko, Egiten eta Eginda adibidez, aldi bereko lana mugatuz etengabe aurrera egin dezan."},{"id":"wip","g":"agile","word":"WIP muga","text":"WIP abian den lana da. WIP muga zutabe batek aldi berean izan beharko lukeen gehienezko txartel kopurua da, taldeak gehiago hasi aurretik gauzak amai ditzan.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"Taldearen egiaztapen-zerrenda laburra «amaituta» zer den esateko, probatuta eta azalduta adibidez, txartel bat zuri eman aurretik. Bere bikia, Definition of Ready, txartel bat hasteko bezain argi noiz dagoen esaten du.","also":["hasteko prest egotearen definizioa","Definition of Ready","DoD","DoR"]},{"id":"retro","g":"agile","word":"Retro","text":"Taldeak nola lan egiten duen aldizka atzera begiratzea, hurrengorako hobekuntza bat edo bi adosteko. Erretrospektiba hitzaren laburdura da. AI-gilen retro batek taldearen lan egiteko moduan aldaketa bat proposatzen du, eta zuk Go edo Oraindik ez esaten duzu.","also":["retroak","erretrospektiba","erretrospektibak"]},{"id":"swarm","g":"agile","word":"Erlauntza","text":"Denek beste lanak utzi eta premiazko gauza bat elkarrekin konpontzea, amaitu arte. AI-gilen talde guztiek proiektu batean laguntzen dute, beste proiektuak zain dauden bitartean.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Scrumen, taldeari ondo lan egiten laguntzen dion pertsona: oztopoak kendu, bilerak bideratu eta ohitura onak irakasten ditu, agindu gabe. AI-gilen Lead Scrum Masterrak trabatutako txartelak atzeman, taldeak mugiarazi eta proiektu guztietan zain dagoena gogorarazten dizu.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Urrats txikitan lan egitea: pixka bat eraiki, emaitzak maiz erakutsi, iritzietatik ikasi eta plana moldatu, dena hasieran planifikatu beharrean.","also":["garapen arina","lan egiteko modu arinak","Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile manifestua","text":"Software sortzaileek 2001ean idatzitako testu laburra. Pertsonak, funtzionatzen duten emaitzak, bezeroekin elkarlana eta aldaketetara egokitzea lehenesten ditu, plan zurrunen eta paper lanen aurretik.","also":["Software garapen arinaren manifestua","Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Ur jauzi eredua","text":"Lan egiteko modu zaharragoa: dena planifikatu, gero dena eraiki eta gero dena probatu, etapaz etapa. Berandu egindako aldaketak zailak eta garestiak dira.","also":["waterfall","ur jauzi eredua","waterfall model"]},{"id":"iteration","g":"agile","word":"Iterazioa","text":"Zerbait eraiki, egiaztatu eta hobetzeko txanda bat. Lan arina halako txanden katea da, eta sprinta horietako mota bat da.","also":["iterazioak","iterations"]},{"id":"increment","g":"agile","word":"Gehikuntza","text":"Sprint edo lan txanda batean produktuari gehitutako zati erabilgarria, aurretik zegoenarekin bat datorrena.","also":["gehikuntzak","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Lan egiteko modu arin ezaguna: talde txikiak sprint laburretan dihardu helburu baterantz, eginkizun jakinekin eta planifikatu, berrikusi eta hobetzeko ohiko bilerekin."},{"id":"scrumteam","g":"agile","word":"Scrum taldea","text":"Scrumen lana egiten duen talde txikia: product owner bat, Scrum Master bat eta garatzaileak.","also":["Scrum taldeak","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum ekitaldiak","text":"Scrumen ohiko bilerak: sprintaren plangintza, eguneroko bilera, berrikuspena eta atzera begirakoa. Askok zeremoniak deitzen diete.","also":["zeremoniak","Scrum zeremoniak","Scrum ceremonies","ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprintaren plangintza","text":"Sprintaren hasierako bilera, zergatik den garrantzitsua, zer txartel hartu eta nola hasi adosteko.","also":["plangintza bilera","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprintaren helburua","text":"Sprintaren zertarakoa azaltzen duen esaldia. Zeregin txikiak alda daitezke helburua betetzen bada.","also":["sprint helburuak","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog-a","text":"Oraingo sprinterako aukeratutako txartelak eta haiek egiteko taldearen plana.","also":["sprinteko lan zerrendak","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog-a","text":"Produkturako egin litekeen guztiaren zerrenda ordenatua, garrantzitsuena goian. Ikasi ahala aldatzen da.","also":["produktuaren lan zerrendak","product backlogs"]},{"id":"productgoal","g":"agile","word":"Produktuaren helburua","text":"Produktuarekin lortu nahi den emaitza nagusia, hurrengo lana aukeratzen laguntzen duena.","also":["produktu helburuak","product goals"]},{"id":"refinement","g":"agile","word":"Backlog-a fintzea","text":"Lan zerrenda aldizka berrikustea, txartelak txukundu, zatitu, ordenatu eta zehazteko, hartzeko prest egon daitezen. Backlog grooming ere esaten zaio.","also":["backlog grooming","refinement","fintzea"]},{"id":"sprintreview","g":"agile","word":"Sprintaren berrikuspena","text":"Sprintaren amaierako bilera, amaitutakoa erakutsi eta iritziak jasotzeko, ondorengoa erabakitzeko.","also":["sprint berrikuspenak","sprint reviews"]},{"id":"demo","g":"agile","word":"Erakustaldia","text":"Amaitutako lana zuzenean martxan erakustea eskatu dutenei.","also":["erakustaldiak","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Denbora muga","text":"Zerbaitetarako finkatutako denbora. Agortzean gelditu egiten zara, dena amaitu ez bada ere.","also":["denbora muga","denbora mugak","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Abiadura","text":"Taldeak sprint batean amaitu ohi duen lana, hurrengoa planifikatzeko. Ez du jendearen ahalegina puntuatzen.","also":["taldearen abiadura","team velocity"]},{"id":"capacity","g":"agile","word":"Edukiera","text":"Taldeak aldi batean har dezakeen lana, oporrak eta beste egitekoak kontuan hartuta.","noTip":1},{"id":"burndown","g":"agile","word":"Geratzen den lanaren grafikoa","text":"Sprintean geratzen den lana egunez egun jaisten erakusten duen grafikoa. Lerroa laua bada, zerbait trabatu da.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Amaitutako lanaren grafikoa","text":"Amaitutako lana denborarekin igotzen erakusten duen grafikoa, aurreikusitako guztizkoaren ondoan, helmugara noiz helduko zaren ikusteko.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban taula","text":"Taula bera: lan etapa bakoitzeko zutabe bat, eta haietan zehar mugitzen diren txartelak.","also":["Kanban taulak","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Tiratze sistema","text":"Norbait lana hartzeko moduan dagoenean soilik hastea lan berria, beteta dagoenari gehiago eman beharrean.","also":["pull-based","pull sistema"]},{"id":"flow","g":"agile","word":"Fluxua","text":"Lana taulan zehar zein erraz mugitzen den. Fluxu onarekin txartelak mugitzen dira, pilatu beharrean.","also":["lan fluxua","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Eskaeratik amaierara arteko denbora","text":"Zerbait eskatzen denetik amaitzen den arteko denbora.","also":["entrega denborak","lead times"]},{"id":"cycletime","g":"agile","word":"Ziklo denbora","text":"Txartel batean lanean benetan hasten denetik amaitu arteko denbora.","also":["ziklo denborak","cycle times"]},{"id":"throughput","g":"agile","word":"Amaitze erritmoa","text":"Aste batean edo beste aldi jakin batean zenbat txartel amaitzen diren.","also":["throughput","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Botila lepoa","text":"Lana pilatzen den eta atzetik datorren guztia moteltzen duen etapa, botila baten lepo estua bezala.","also":["botila lepoak","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Taulako lerroa","text":"Mota bereko txartelak biltzen dituen lerro horizontala, premiazkoak edo talde batenak adibidez.","also":["taulako lerroak","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Alferrikako lana (bezeroari laguntzen ez dion guztia) kendu eta lana etengabe mugitzen mantentzen duen lan egiteko modua."},{"id":"waste","g":"agile","word":"Alferrikako lana","text":"Leanen, bezeroari laguntzen ez dion ahalegin oro: itxarotea, lana errepikatzea edo inork erabiltzen ez duen zerbait egitea.","noTip":1},{"id":"kaizen","g":"agile","word":"Etengabeko hobekuntza","text":"Aldaketa txiki erregularrekin hobetzen joatea eta lagundu duten egiaztatzea. Atzera begirakoak modu bat dira; kaizen ere esaten zaio.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Bere burua antolatzen duen taldea","text":"Lana nola egin bere kabuz erabakitzen duen taldea, urratsez urratseko agindurik gabe.","also":["autoantolatua","talde autogestionatua","self-managing team","self-organising"]},{"id":"crossfunc","g":"agile","word":"Diziplina anitzeko taldea","text":"Lana bere kabuz amaitzeko behar dituen trebetasun guztiak dituen taldea, diseinatu, eraiki eta probatzeko adibidez.","also":["diziplina anitzekoa","cross-functional"]},{"id":"spike","g":"agile","word":"Ikerketa mugatua","text":"Benetako lanari ekin aurretik galdera bat argitzeko ikerketa laburra, denbora mugatuarekin.","also":["spikes"]},{"id":"rework","g":"agile","word":"Lana berriz egitea","text":"Lana berriro egitea, lehen aldian ondo atera ez zelako.","also":["berregina","reworked"]},{"id":"safe","g":"agile","word":"Agile eskala handian (SAFe)","text":"Erakunde handi bateko talde askotan Agile erabiltzeko moduak. SAFe adibide ezaguna da.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Proiektuaren kode karpeta, commit-en historia osoarekin. Zure ordenagailuan, GitHuben edo bietan egon daiteke.","also":["repositorioa"]},{"id":"branch","g":"build","word":"Branch","text":"Kodeko lan-lerro bereizi bat, aldaketak bertsio nagusia ukitu gabe egiteko.","also":["branchak","branch-ak"]},{"id":"commit","g":"build","word":"Commit","text":"Kodearen argazki gordea, aldatutakoaren ohar labur batekin. Beti itzul zaitezke horietako batera.","also":["commitak","commit-ak"]},{"id":"push","g":"build","word":"Push","text":"Gordetako une kopiak, commit-ak, ordenagailu honetatik sareko kopia partekatura bidaltzea, GitHubera adibidez, babestuta gera daitezen eta besteek eskuratu ahal izan ditzaten."},{"id":"merge","g":"build","word":"Merge","text":"Adar bateko aldaketak beste batera elkartzea, normalean bertsio nagusira."},{"id":"pr","g":"build","word":"Pull request","text":"Adar bateko aldaketak egiaztatu eta bertsio nagusian batzeko eskatzea. Webgune batzuek merge request deitzen diote.","also":["PR","PRs","batze eskaera","merge request"]},{"id":"refactor","g":"build","word":"Refactor","text":"Kodea txukuntzea egiten duena aldatu gabe: fitxategi txikiagoak, izen argiagoak, errepikapen gutxiago."},{"id":"bug","g":"build","word":"Bug","text":"Behar bezala ez dabilen zerbait.","also":["bugak","bug-ak"]},{"id":"peerreview","g":"build","word":"Berdinen arteko berrikuspena","text":"Beste begirada bat: egilea ez den norbaitek lana zuregana iritsi aurretik egiaztatzen du, akats gutxiago pasatzeko. AI-gilen beste AI batek txartel bakoitza egiaztatzen du.","also":["kode-berrikuspena","code review","peer review"]},{"id":"code","g":"build","word":"Kodea","text":"Ordenagailuari zer egin esaten dioten idatzizko argibideak. Iturburu kodea ere esaten zaio.","also":["iturburu kodea","source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programazio lengoaia","text":"Kodea idazteko lengoaia, JavaScript, Python edo Java adibidez. Bakoitza lan mota batzuetarako da egokiagoa.","also":["programazio lengoaiak","programming languages"]},{"id":"developer","g":"build","word":"Garatzailea (dev)","text":"Kodea idatzi eta aldatzen duen pertsona. Programatzailea edo software ingeniaria ere esaten zaio.","also":["garatzailea","garatzaileak","programatzailea","programatzaileak","software ingeniaria","developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Softwarea","text":"Ordenagailu eta telefonoetan dabiltzan programak; makinak berak, aldiz, hardwarea dira.","noTip":1},{"id":"app","g":"build","word":"App-a","text":"Aplikazioa: telefonoan, ordenagailuan edo nabigatzailean zerbait egiteko programa.","also":["app-ak","aplikazioa","aplikazioak","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web aplikazioa","text":"Nabigatzailean dabilen aplikazioa; ez da ezer instalatu behar.","also":["web aplikazioak","web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"Ikusten eta sakatzen duzun aplikazioaren zatia: pantailak, botoiak eta testuak, sarritan nabigatzailean.","also":["front-end","frontend","ikusgai dagoen zatia"]},{"id":"backend","g":"build","word":"Back end","text":"Datuak gordetzen dituen eta zerbait sakatzean lana egiten duen aplikazioaren barneko zatia, pasahitza egiaztatzea adibidez.","also":["back-end","backend","barneko zatia"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Aplikazioaren ikusgai dagoen zatian zein barneko zatian lan egitea.","also":["full-stack"]},{"id":"ui","g":"build","word":"Erabiltzaile interfazea (UI)","text":"Pertsonak pantailan ikusi eta erabiltzen duena: antolaketa, botoiak, menuak eta testuak.","also":["UI","erabiltzaile interfazea","user interface"]},{"id":"ux","g":"build","word":"Erabiltzaile esperientzia (UX)","text":"Zerbait erabiltzean nola sentitzen den pertsona: erraza, argia eta atsegina den, edo nahasgarria eta motela.","also":["UX","erabiltzaile esperientzia","user experience"]},{"id":"accessibility","g":"build","word":"Irisgarritasuna (a11y)","text":"Gauzak guztiek erabiltzeko moduan egitea, gutxi ikusten dutenek, sagua erabili ezin dutenek edo pantaila irakurgailua darabiltenek barne.","also":["a11y"]},{"id":"responsive","g":"build","word":"Diseinu moldagarria","text":"Orriak edozein pantaila tamainatara egokitu eta ondo ibiltzea, telefonotik monitore handira.","also":["diseinu egokigarria"]},{"id":"designsys","g":"build","word":"Diseinu sistema","text":"Partekatutako kolore, letra, botoi eta arauen multzoa, pantaila guztiek itxura eta portaera koherenteak izan ditzaten.","also":["diseinu sistemak","design systems"]},{"id":"architecture","g":"build","word":"Arkitektura","text":"Sistema baten egitura orokorra: atal nagusiak eta elkarren artean nola komunikatzen diren."},{"id":"database","g":"build","word":"Datu basea (DB)","text":"Informazioa antolatuta gordetzeko tokia, aplikazioak irakurri eta alda dezakeen kalkulu orri oso indartsu baten antzekoa.","also":["datu basea","datu baseak","DB","database","databases"]},{"id":"schema","g":"build","word":"Datu basearen eskema","text":"Datu basearen antolaketa: zer informazio taula dituen eta bakoitzean zer sartzen den.","also":["eskema","schema"]},{"id":"sql","g":"build","word":"SQL","text":"Datu base askori informazioa eskatzeko edo aldatzeko lengoaia. Izenak «kontsulta lengoaia egituratua» esan nahi du.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Datuak","text":"Ordenagailuan gordetako informazioa, izenak, eskaerak edo ezarpenak adibidez.","also":["datu multzoa","datu multzoak","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Zerbitzaria","text":"Beti piztuta dagoen eta beste ordenagailuen eskaerei erantzuten dien ordenagailua, bisitatzean web orria bidaltzea adibidez.","also":["zerbitzariak","servers"]},{"id":"client","g":"build","word":"Bezeroa","text":"Zerbitzariari zerbait eskatzen dion aldea, normalean nabigatzailea edo aplikazioa. Negozioetan zerbitzua erosten duen pertsona ere bada.","also":["bezeroak","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Aplikazioak programatzeko interfazea: programa batek beste bati egin diezazkiokeen eskaeren menu finkoa, eguraldi zerbitzu bati gaurko iragarpena eskatzea adibidez.","also":["APIs","aplikazioak programatzeko interfazea","application programming interface"]},{"id":"endpoint","g":"build","word":"Sarbide puntua","text":"API baten aukeretako bat: programa batek informazioa jasotzeko edo bidaltzeko erabil dezakeen web helbidea.","also":["sarbide puntuak","endpoints"]},{"id":"integration","g":"build","word":"Integrazioa","text":"Bi sistema elkarrekin lan egiteko lotzea, dendako eskaerak kontabilitate programara bidaltzea adibidez.","also":["integrazioak","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Zerbait gertatzean sistema batek beste bati bere kabuz bidaltzen dion mezua, «ordainketa jasota» adibidez.","also":["webhooks"]},{"id":"library","g":"build","word":"Liburutegia","text":"Beste norbaitek idatzitako kodea, zuk berriro idatzi beharrean erabil dezakezuna.","also":["liburutegiak","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework-a","text":"Aplikazioa eraikitzeko egitura prestatua, kodearen antolaketa neurri handi batean zehazten duena, etxearen hezurdura bezala.","also":["lan esparruak","frameworks"]},{"id":"sdk","g":"build","word":"Softwarea garatzeko tresna multzoa (SDK)","text":"Plataforma edo zerbitzu baterako softwarea sortzeko tresna, kode eta adibideen multzoa.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software mendekotasuna","text":"Kodeak funtzionatzeko behar duen liburutegia edo tresna. Eguneratuta edukitzea garrantzitsua da segurtasunerako.","also":["software mendekotasunak","software dependencies"]},{"id":"package","g":"build","word":"Paketea","text":"Proiektu batean instalatu eta erabil dezakezun kode prestatuaren multzoa.","also":["paketeak","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Pakete kudeatzailea","text":"Kodeak behar dituen paketeak eskuratu eta eguneratzen dituen tresna. npm oso ohikoa da.","also":["pakete kudeatzaileak","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Kode aldaketen historia gordetzeko tresnarik erabiliena, commit eta adarren bidez."},{"id":"github","g":"build","word":"GitHub","text":"Git biltegiak sarean gordetzen dituen webgunea, taldeek kodea partekatu, aldaketak berrikusi eta lana jarraitzeko."},{"id":"vcs","g":"build","word":"Bertsio kontrola","text":"Fitxategietako aldaketa guztien historia gordetzea, nork zer aldatu duen ikusteko eta behar denean atzera egiteko. Gitek hori egiten du.","also":["iturburu kontrola","bertsio kontrol sistema","source control","version control system"]},{"id":"clone","g":"build","word":"Klonatu","text":"Biltegi baten kopia osoa zure ordenagailuan egitea, historia barne.","also":["klonatua","klonatzea","cloning","cloned"]},{"id":"pull","g":"build","word":"Pull","text":"Partekatutako kopiako azken commit-ak zure ordenagailura ekartzea, GitHubetik adibidez. Push-en aurkakoa da.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Adar nagusia","text":"Denek abiapuntutzat erabiltzen duten kodearen bertsio ofiziala, sarritan main edo master izenekoa.","also":["master adarra","master branch"]},{"id":"conflict","g":"build","word":"Batze gatazka","text":"Bi aldaketak lerro berak modu desberdinean ukitzen dituztenean gertatzen da: ordenagailuak ezin ditu elkartu, eta pertsona batek aukeratu behar du.","also":["batze gatazkak","merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"Bi bertsioren arteko aldaketa zehatzak erakusten dituen ikuspegia: gehitutako eta kendutako lerroak.","also":["diffs","desberdintasunak"]},{"id":"fork","g":"build","word":"Fork","text":"Beste norbaiten biltegiaren zure kopia, jatorrizkoari eragin gabe alda dezakezuna.","also":["forks","forked","adarkatzea"]},{"id":"script","g":"build","word":"Script","text":"Lan bat bere kabuz egiten duen programa laburra, fitxategiak txukundu edo aplikazioa abiaraztea adibidez.","also":["scripts","scriptak"],"noTip":1},{"id":"build","g":"build","word":"Eraikuntza","text":"Kodea exekutatzeko prest dagoen zerbait bihurtzea, edo emaitza prest hori bera.","also":["eraikuntzak","builds"],"noTip":1},{"id":"compile","g":"build","word":"Konpilatu","text":"Pertsonek idatzitako kodea ordenagailuak zuzenean exekuta dezakeen forma bihurtzea.","also":["konpilatua","konpilatzailea","konpilazioa","compiler"]},{"id":"cli","g":"build","word":"Komando lerroa (CLI)","text":"Klik egin beharrean ordenagailuari argibideak idazteko testu leihoa. Terminala ere esaten zaio.","also":["komando lerroa","command line","command-line","CLI","terminala","terminal"]},{"id":"config","g":"build","word":"Konfigurazioa","text":"Softwarearen portaera kontrolatzen duten ezarpenak, kodetik bereizita gordeta erraz aldatzeko.","also":["config","konfigurazioa","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Ingurune aldagaia","text":"Programa abiatzean ematen zaion ezarpena, sarritan helbide edo pasahitzetarako, kodean idatzi beharrik ez izateko.","also":["ingurune aldagaiak","environment variables","env var"]},{"id":"debugging","g":"build","word":"Arazketa","text":"Zerbait zergatik ez dabilen bilatu eta konpontzea.","also":["araztu","araztua","debug","debugged"]},{"id":"pairing","g":"build","word":"Binakako programazioa","text":"Bi pertsona, edo pertsona bat eta AI bat, kode berean elkarrekin aritzea: batek idatzi eta besteak egiaztatzen du.","also":["binaka aritzea","pairing"]},{"id":"docs","g":"build","word":"Dokumentazioa","text":"Zerbait nola dabilen edo nola erabili azaltzen duten idazkiak.","also":["dokumentazioa","docs","documentation"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Biltegi batean lehenik irakurri beharreko fitxategia: proiektua zer den eta nola abiarazi.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Sistema zaharra","text":"Oraindik erabiltzen den sistema zaharra, aldatzeko zaila, sarritan jende gutxik ulertzen duelako.","also":["sistema zaharrak","kode zaharra","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Zor teknikoa","text":"Orain denbora aurreztu baina geroko aldaketak moteltzen dituzten lasterbideak, interesak pilatzen dituen mailegua bezala. Kodea berrantolatzeak zorra gutxitzen du.","also":["tech debt"]},{"id":"test","g":"test","word":"Proba","text":"Zerbait behar bezala dabilela egiaztatzea. Proba batzuk ordenagailuak egiten ditu kodea aldatzean; besteetan zuk amaitutako txartela probatzen duzu onartu aurretik.","also":["probak","probatu","probatzeko","probaren"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"QA kalitatea ziurtatzea da: argitaratu aurretik lana ondo dagoela ziurtatzeko egiten den guztia. AI-gilen egiaztapen automatikoak dira: QA gorri badago, zerbaitek huts egin du eta ezin da argitaratu konpondu arte.","also":["kalitate-kontrola","kalitate-kontrolak","kalitatearen bermea"]},{"id":"testpile","g":"test","word":"Proba-pila","text":"Zuk probatzeko zain dauden amaitutako txartelak, bata bestearen atzetik. Onartu bat edo itzuli ohar batekin, eta hurrengoa agertzen da.","also":["proba-pilak"]},{"id":"autotest","g":"test","word":"Proba automatizatua","text":"Kodea aldatzen denean ordenagailuak bere kabuz egiten duen egiaztapena, akatsak goiz atzemateko.","also":["proba automatizatuak","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Eskuzko proba","text":"Pertsona batek lana eskuz probatzea, behar bezala dabilen ikusteko.","also":["eskuzko probak","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unitate proba","text":"Kode zati oso txiki bat bakarka egiaztatzen duen proba automatikoa.","also":["unitate probak","unit tests"]},{"id":"integtest","g":"test","word":"Integrazio proba","text":"Hainbat atal elkarrekin ondo dabiltzala egiaztatzea, ez soilik banaka.","also":["integrazio probak","integration tests"]},{"id":"endtoend","g":"test","word":"Muturretik muturrerako proba (E2E)","text":"Benetako erabiltzaile baten moduan hasieratik amaierara aritzen den proba: izena eman, erosi eta ordaindu, adibidez.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"Erabiltzailearen onarpen probak (UAT)","text":"Lana eskatu dutenek probatzen dute eta behar dutena betetzen duen esaten dute. AI-gileren proba pila horren bertsioa da.","also":["UAT","onarpen probak","acceptance testing"]},{"id":"regression","g":"test","word":"Erregresioa","text":"Lehen bazebilen baina aldaketa baten ondoren hondatu den zerbait. Erregresio probek lehengoak oraindik badabiltzala egiaztatzen dute.","also":["erregresioak","erregresio proba","erregresio probak","regression testing","regressions","regression test","regression tests"]},{"id":"smoke","g":"test","word":"Oinarrizko funtzionamendu proba","text":"Gauza nagusiak badabiltzala oso azkar egiaztatzea, aldaketa argitaratu ondoren adibidez. Huts egiten badu, gelditu eta begiratu.","also":["smoke tests","ke probak"]},{"id":"exploratory","g":"test","word":"Esplorazio probak","text":"Produktua askatasunez eta modu desberdinetan probatzea, aurrez prestatutako probek aurkituko ez lituzketen arazoak bilatzeko.","also":["esplorazio proba","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Proba kasua","text":"Probatzeko idatzitako egoera bat: urratsak eta zer gertatu beharko litzatekeen.","also":["proba kasuak","test cases"]},{"id":"coverage","g":"test","word":"Proben estaldura","text":"Proba automatikoek kodearen zenbateko zatia egiaztatzen duten. Gehiago normalean seguruagoa da, baina horrek bakarrik ez du funtzionamendu ona frogatzen.","also":["estaldura","kode estaldura","code coverage"]},{"id":"testdata","g":"test","word":"Proba datuak","text":"Probetan erabilitako adibide asmatuak, benetako pertsonen datu pribatuak agerian ez uzteko.","also":["proba laginak","test fixtures"]},{"id":"edgecase","g":"test","word":"Muga kasua","text":"Ezohiko muturreko egoera, formulario hutsa edo apostrofodun izena adibidez, non gauzak sarritan hondatzen diren.","also":["muga kasuak","edge cases"]},{"id":"happypath","g":"test","word":"Bide ideala","text":"Dena ondo doan ohiko ibilbidea. Proba onek arazoak dituzten bideak ere aztertzen dituzte."},{"id":"perftest","g":"test","word":"Errendimendu probak","text":"Zerbait zein azkarra den eta presiopean nola moldatzen den egiaztatzea.","also":["errendimendu proba","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Karga probak","text":"Jende askok aldi berean erabiltzean sistema nola moldatzen den egiaztatzea.","also":["karga proba","load test","load tests"]},{"id":"sectest","g":"test","word":"Segurtasun probak","text":"Sistema gaizki erabiltzeko edo ikusi behar ez dena ikusteko aukera eman dezaketen ahulguneak bilatzea.","also":["segurtasun proba","security test","security tests"]},{"id":"accesstest","g":"test","word":"Irisgarritasun probak","text":"Gaitasun desberdineko pertsonek produktua erabil dezaketela egiaztatzea, pantaila irakurgailuarekin edo teklatu hutsarekin ere bai.","also":["irisgarritasun proba","accessibility test"]},{"id":"linting","g":"test","word":"Kodearen egiaztapen automatikoa","text":"Kodeko balizko akatsak eta estilo nahasia atzematen dituen egiaztapen automatikoa, programentzako zuzentzaile ortografikoa bezala.","also":["linter","lint"]},{"id":"static","g":"test","word":"Analisi estatikoa","text":"Kodea automatikoki irakurriz arazoak bilatzea, exekutatu gabe.","also":["kodearen analisi estatikoa","static code analysis"]},{"id":"flaky","g":"test","word":"Proba ezegonkorra","text":"Batzuetan gainditu eta besteetan huts egiten duen proba, arrazoi argirik gabe; ezin da guztiz fidatu.","also":["proba ezegonkorrak","flaky tests"]},{"id":"repro","g":"test","word":"Akatsa errepikatu","text":"Urrats berak jarraituz akatsa nahita berriro gertaraztea, aztertu eta konpontzeko. Urrats horiek idaztea da akats txostenaren zatirik erabilgarriena.","also":["repro","errepikatu","errepikatzeko urratsak","steps to reproduce","reproduce"]},{"id":"severity","g":"test","word":"Larritasuna","text":"Arazo baten eragina zein larria den, eragozpen txikitik dena gelditzeraino.","also":["larritasun maila","severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Softwarearen bertsio berria martxan izango duten ordenagailuetara kopiatzea, proba kopia batera edo benetako zerbitzura adibidez."},{"id":"release","g":"change","word":"Argitalpena","text":"Izena duen amaitutako lan-sorta bat, batera zuzenean jartzen dena, zer aldatu den azaltzen duten ohar laburrekin. 🚀 Argitalpenak eginda dauden txarteletatik idazten ditu oharrak.","also":["argitalpenak","release","bertsioa"]},{"id":"rollback","g":"change","word":"Atzera egitea","text":"Bertsio berriak arazoak ematean azken bertsio onera itzultzea. AI-gilen, Atzera egin aukerak aldaketa bakoitza desegiteko urratsak zerrenda bakarrean biltzen ditu.","also":["rollback","atzera egin","atzera egin da"]},{"id":"live","g":"change","word":"Zuzenean","text":"Jendeak erabiltzen duen benetako bertsioa, gauzak probatzeko kopia baten aldean. Garatzaileek ekoizpena ere esaten diote.","also":["ekoizpena","live","produkzioa"],"noTip":1},{"id":"change","g":"change","word":"Aldaketa","text":"Jendeak behar duen zerbaitean planifikatutako aldaketa bat, aurrez idatzita: zer, zergatik, arriskua, noiz eta nola desegin. Hasi bat 🔀 Aurkeztu aldaketa bat botoiarekin.","also":["aldaketak","aldaketa-eskaera","aldaketa-eskaerak"],"noTip":1},{"id":"risk","g":"change","word":"Arriskua","text":"Gaizki atera daitekeen zerbait, zein litekeen eta zein larria litzatekeen kontuan hartuta puntuatua. ⚠️ Arriskuak zerrenda bakarrean gordetzen ditu, puntuazio altuena lehenik, bakoitza berriro begiratzeko data batekin.","also":["arriskuak","arrisku-erregistroa"]},{"id":"chgwin","g":"change","word":"Aldaketa-leihoa","text":"Aldaketak zuzenean jar daitezkeen uneak, adibidez astearte arratsalde lasai bat. Leiho batetik kanpo ezin da aldaketa-txartel bat amaitu, larrialdi bat ez bada.","also":["aldaketa-leihoak"]},{"id":"gonogo","g":"change","word":"Go / No go","text":"Aldaketa argitaratu aurreko azken egiaztapena: onartu behar duen bakoitzak Go edo No go dio. Denek Go esaten dutenean soilik jarraitzen da.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Onarpena","text":"Lana hasi aurretik bai baten zain egotea. Lagun batek sortzen duen txartela, edo aldaketa bat, ✅ Onarpenak atalean itxaroten du zuk onartu edo baztertu arte.","also":["onarpenak"]},{"id":"quiettime","g":"change","word":"Ordu isila","text":"Ezer argitaratzen ez den aldia, zuzeneko emanaldi, erakustaldi edo gauean adibidez. Taldeek lanean eta probak egiten jarraitzen dute, baina argitalpenak amaiera arte itxaroten du; beste toki batzuetan aldaketak izoztea esaten zaio.","also":["ordu isilak","aldaketa-izozketa","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Softwarea eraikitzen eta martxan mantentzen dutenek talde bakarrean lan egitea, automatizazio handiarekin, aldaketak maiz eta seguru argitaratzeko."},{"id":"cicd","g":"change","word":"CI/CD (etengabeko integrazioa eta entrega)","text":"Denen aldaketak bertsio nagusian maiz elkartu eta automatikoki egiaztatzen dira: hori da etengabeko integrazioa. Horrela softwarea beti dago botoi bat sakatuta argitaratzeko prest: etengabeko entrega.","also":["CI/CD","CI","CD","etengabeko integrazioa","etengabeko entrega","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Etengabeko hedapena","text":"Etengabeko entregatik urrats bat harago: probak gainditzen dituen aldaketa bakoitza bere kabuz argitaratzen da, botoirik sakatu gabe.","also":["etengabeko hedapenak","continuous deployments"]},{"id":"pipeline","g":"change","word":"Urrats kate automatikoa","text":"Aldaketa bat argitaratu arteko urrats automatikoen segida, eraiki, probatu eta hedatu adibidez.","also":["pipelines"]},{"id":"environment","g":"change","word":"Ingurunea","text":"Helburu jakin baterako sistemaren kopia bereizia, garatzeko, probatzeko edo benetako zerbitzua emateko adibidez.","also":["inguruneak","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Garapen ingurunea","text":"Garatzaileak lan egiteko erabiltzen duen kopia, sarritan bere ordenagailuan, non gauzak hondatzeak inori kalterik egiten ez dion.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Proba ingurunea","text":"Probak egiteko soilik erabiltzen den kopia bereizia, benetako zerbitzua ukitu gabe.","also":["proba inguruneak","test environments"]},{"id":"staging","g":"change","word":"Aurreprodukzioa","text":"Benetako sistemaren moduan prestatutako azken kopia, aldaketa argitaratu aurretik azken egiaztapena egiteko.","also":["aurreprodukzio ingurunea","staging environment"]},{"id":"artifact","g":"change","word":"Eraikuntzaren emaitza","text":"Eraikuntzak sortzen duen fitxategia edo paketea, gordetzeko, egiaztatzeko edo argitaratzeko prest.","also":["eraikuntzaren emaitzak","build artifacts"]},{"id":"hotfix","g":"change","word":"Premiazko konponketa","text":"Ohiko planetik kanpo azkar argitaratutako konponketa, zerbait garrantzitsua hondatu delako.","also":["premiazko konponketak","hotfixes"]},{"id":"patch","g":"change","word":"Adabakia","text":"Akatsa edo segurtasun zuloa konpontzen duen eguneratze txikia. Segurtasun adabakiak azkar aplikatzea garrantzitsua da.","also":["adabakiak","segurtasun adabakia","segurtasun adabakiak","security patches","patches","security patch"]},{"id":"version","g":"change","word":"Bertsio zenbakia","text":"Zein bertsio duzun dioen etiketa, 2.4.1 adibidez. Sarritan lehen zenbakia aldaketa handiekin aldatzen da eta azkena konponketa txikiekin.","also":["bertsio zenbakiak","bertsio zenbaketa semantikoa","semantic versioning","version numbers"]},{"id":"relnotes","g":"change","word":"Bertsio oharrak","text":"Bertsio bateko aldaketen zerrenda labur eta argia, konponketak eta muga ezagunak barne. Aldaketen erregistroa ere esaten zaio.","also":["aldaketen erregistroa","changelog","change log"]},{"id":"flag","g":"change","word":"Funtzionaltasun etengailua","text":"Funtzio berria ezkutuan argitaratu eta bertsio berririk gabe piztu edo itzaltzeko etengailua.","also":["funtzionaltasun etengailuak","feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Bertsio berri batekin konpontzea","text":"Bertsio akastuna azkar beste bertsio zuzendu bat argitaratuz konpontzea, zaharrera itzuli beharrean.","also":["roll forward","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary argitalpena","text":"Aldaketa lehenik talde txiki bati eta, ondo badoa, guztiei argitaratzea. Izena meatzariei arriskuaz ohartarazteko erabiltzen ziren kanarioetatik dator.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Hedapen urdin-berdea","text":"Benetako sistemaren bi kopia edukitzea eta jendea aldi batean berrira pasatzea, huts eginez gero berehala atzera itzultzeko.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Etenik gabeko hedapena","text":"Bertsio berria argitaratzea erabiltzaileentzako zerbitzua inoiz gelditu gabe.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Aldaketak ahalbidetzea","text":"Aldaketak ondo ateratzen laguntzea: arriskua neurtu, dagokion onarpena lortu eta une egokia aukeratzea. Aldaketen kudeaketa ere esaten zaio.","also":["aldaketen kudeaketa","change management"]},{"id":"cab","g":"change","word":"Aldaketen aholku batzordea (CAB)","text":"Aldaketa garrantzitsuak aztertu eta aurrera egin dezaketen eta noiz adosten duen taldea.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Aldaketa estandarra","text":"Beti modu frogatu berean egiten den arrisku txikiko aldaketa; horregatik, aldez aurretik onartuta dago.","also":["aldaketa estandarrak","standard changes"]},{"id":"normchange","g":"change","word":"Aldaketa arrunta","text":"Egin aurretik egiaztatu eta onartu behar den aldaketa.","also":["aldaketa arruntak","normal changes"]},{"id":"emergchange","g":"change","word":"Larrialdiko aldaketa","text":"Arazo larria konpontzeko edo saihesteko berehala egin beharreko aldaketa, onarpen azkarragoarekin.","also":["larrialdiko aldaketak","emergency changes"]},{"id":"automation","g":"change","word":"Automatizazioa","text":"Errepikatzen den lana ordenagailuak bere kabuz egitea, azkarrago eta beti modu berean.","also":["automatizatua","automated"],"noTip":1},{"id":"infra","g":"change","word":"Azpiegitura","text":"Softwarea martxan dagoen makina, sare eta zerbitzuak.","also":["infra"]},{"id":"iac","g":"change","word":"Azpiegitura kode gisa (IaC)","text":"Zerbitzariak eta ezarpenak kodearekin gordetako fitxategietan deskribatzea, beti berdin berreraikitzeko.","also":["IaC"]},{"id":"cloud","g":"change","word":"Hodeia","text":"Hornitzaile handi bati ordenagailuak, biltegiratzea eta zerbitzuak internet bidez alokatzea, makinak zeureak izan beharrean.","also":["hodeiko konputazioa","cloud computing","the cloud"]},{"id":"provider","g":"change","word":"Hodei hornitzailea","text":"Internet bidez baliabide informatikoak alokatzen dituen enpresa, Amazon Web Services (AWS), Microsoft Azure edo Google Cloud adibidez.","also":["hodei hornitzaileak","cloud providers"]},{"id":"hosting","g":"change","word":"Ostatatzea","text":"Aplikazioa edo webgunea jendearentzat eskuragarri egoteko martxan dagoen tokia, normalean enpresa bati alokatua.","also":["ostatatua"]},{"id":"domain","g":"change","word":"Domeinu izena","text":"Jendeak idazten duen web helbidea, example.com adibidez. Urteka alokatzen da eta berritu egin behar da.","also":["domeinu izenak","domeinua","domain","domain names"]},{"id":"dns","g":"change","word":"DNS","text":"Domeinu izenen sistema: Interneteko helbide liburua, example.com bezalako izen bat dagokion ordenagailuaren helbide bihurtzen duena.","also":["domeinu izenen sistema","domain name system"]},{"id":"container","g":"change","word":"Edukiontzia","text":"Aplikazioa eta behar duen guztia biltzen dituen pakete itxia, edozein ordenagailutan berdin ibiltzeko. Docker da tresnarik ezagunena.","also":["edukiontziak","Docker","containers"],"noTip":1},{"id":"vm","g":"change","word":"Makina birtuala (VM)","text":"Benetako ordenagailu baten barruan dabilen ordenagailu simulatua, makina handi batek askoren lana egin dezan.","also":["VM","VMs","makina birtualak","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Zerbitzariak zeuk zaindu gabe kodea exekutatzea: hornitzaileak behar denean abiarazten du, eta erabilitakoagatik ordaintzen duzu."},{"id":"lb","g":"change","word":"Karga orekatzailea","text":"Bisitariak hainbat zerbitzaritan banatzen ditu, bakar bat ere gainezka ez dadin.","also":["karga orekatzaileak","load balancers"]},{"id":"cache","g":"change","word":"Cachea","text":"Azken emaitzak hurbil gordetzeko tokia, berriro bilatu edo kalkulatu beharrik ez izateko. Hustuz gero, zaharkituta agertzen diren orriak konpon daitezke.","also":["cacheak","caches","caching","cached"]},{"id":"cdn","g":"change","word":"Edukiak banatzeko sarea (CDN)","text":"Orri eta irudien kopiak bisitariengandik gertu gordetzen dituen mundu osoko zerbitzari sarea, azkar kargatzeko.","also":["CDN"]},{"id":"migration","g":"change","word":"Migrazioa","text":"Datuak edo sistemak antolaketa zaharretik berrira eramatea, edo datu basearen egitura kontuz aldatzea.","also":["migrazioak","datu basearen migrazioa","database migration","migrations"]},{"id":"service","g":"run","word":"Zerbitzua","text":"Zuk eraiki duzun eta jendeak behar duen zerbait, webgune edo aplikazio bat adibidez, martxan jarrai dezan zaintzen dena. Markatu «Proiektu hau zerbitzu bat da» eta esan zer eskaintzen duen, nork erabiltzen duen eta nor dagoen guardian.","also":["zerbitzuak"]},{"id":"uptimepct","g":"run","word":"Erabilgarritasun denbora","text":"Zerbitzua denboraren zenbatean dabilen, normalean ehunekotan. %99,9 izanda ere, hilean 43 minutu inguru geldi egon daiteke.","also":["erabilgarritasun ehunekoa","uptime percentage"]},{"id":"uptime","g":"run","word":"Erabilgarritasun-egiaztapena","text":"Egiaztapen automatiko bat, minutu gutxiro, zure zerbitzuak oraindik erantzuten duela ziurtatzeko. Hainbat aldiz jarraian huts egiten badu, AI-gile-k berak irekitzen du intzidente-txartel bat.","also":["erabilgarritasun egiaztapenak","uptime checks"]},{"id":"statuspage","g":"run","word":"Egoera-orria","text":"Zerbitzu batek funtzionatzen duen ala ez erakusten duen orri publikoa (berdea, laranja edo gorria), azken berriarekin, erabiltzaileek galdetu beharrean begiratu ahal izan dezaten.","also":["egoera-orriak"]},{"id":"desk","g":"run","word":"Zerbitzu-mahaia","text":"Zure zerbitzua erabiltzen duten pertsonen galderak eta jakinarazpenak iristen diren lekua. AI-gilek bakoitza eskaera, intzidente edo ideia gisa sailkatzen du, eta abisatu egiten du lehendik jakinarazitako zerbaiten antza duenean.","also":["zerbitzu-mahaiak","mahaia","service desk","laguntza-mahaia"]},{"id":"svcrequest","g":"run","word":"Zerbitzu-eskaera","text":"Norbaitek zerbait arrunta eskatzen du, kontu berri bat edo laguntza pixka bat adibidez, zerbait hautsita dagoela jakinarazi beharrean. Bere txandaren zain geratzen da; intzidentea lehenago doa.","also":["zerbitzu-eskaerak"]},{"id":"incident","g":"run","word":"Intzidentea","text":"Erabiltzaileentzat orain hondatuta edo gaizki dabilen zerbait, webgunea geldituta edo oso motel egotea adibidez. 🔥 intzidente txartelak ilara aurreratzen du: berriro martxan jartzea da lehena.","also":["intzidenteak","gorabehera"]},{"id":"major","g":"run","word":"Intzidente larria","text":"Intzidente handi bat: jende asko kaltetuta, edo dirua edo datuak arriskuan. Botoi batek talde guztiak jartzen ditu horretan (erlauntza), guardian dagoena esnatzen du eta egoeraren berri eskatzen du 30 minuturo.","also":["intzidente larriak","major incident"]},{"id":"oncall","g":"run","word":"Guardian","text":"Zerbait hausten denean erantzuten duena izatea, gauez ere bai. Zerbitzu bakoitzak guardian dagoen talde-kide bat du, bere intzidenteetarako lehenengo esnatzen dena.","also":["guardia","guardiak","on-call"]},{"id":"replyby","g":"run","word":"Erantzun-epea","text":"Txartel batek lehen erantzunaren zain zenbat denbora egon daitekeen, adibidez ordubete intzidente baterako. Ondoren erloju gorri bat jartzen zaio, ezer isilean ahaztu ez dadin. Erantzun-helburua ere deitzen zaio.","also":["erantzun-epeak","erantzun-orduak","erantzun-helburua"]},{"id":"postmortem","g":"run","word":"Intzidentearen ondoko azterketa","text":"Intzidente baten ondoren atzera begiratze labur bat: zer gertatu zen, zerk lagundu zuen eta zer aldatu, inori errua bota gabe. Intzidente bat ezin da itxi hori gabe.","also":["post-mortem","postmortem","ondoko azterketa"]},{"id":"problem","g":"run","word":"Arazoa","text":"Intzidente baten edo gehiagoren atzean ezkutatuta dagoen kausa. 🧩 Arazo-txartel batek behin eta berriz itzultzen diren intzidenteak biltzen ditu, kausa aurkitu eta betiko konpon dadin.","also":["arazoak"],"noTip":1},{"id":"rootcause","g":"run","word":"Kausa nagusia","text":"Zerbait hautsi izanaren benetako arrazoia, ez bakarrik gaizki zihoala ikusi zenuena. Konpondu kausa nagusia eta intzidenteak ez du berriro itzuliko.","also":["kausa nagusiak","oinarrizko kausa","erroko kausa"]},{"id":"workaround","g":"run","word":"Aldi baterako konponbidea","text":"Gauzak martxan mantentzeko modu bat benetako konponketa prest egon arte, adibidez zerbait berrabiaraztea trabatzen denean. Arazo-txartelean idatzita geratzen da, inork berriro asmatu behar ez dezan.","also":["aldi baterako konponbideak","workaround"]},{"id":"knownerror","g":"run","word":"Ezagutzen den errorea","text":"Zergatia ezagutzen den baina oraindik konpondu ez den arazoa, normalean behin-behineko irtenbidea idatzita duena. 🧩 Ezagutzen diren erroreak atalak biltzen ditu, denek irtenbide hori erabil dezaten berriro ikertzen hasi beharrean.","also":["ezagutzen diren erroreak","errore ezaguna"]},{"id":"runbook","g":"run","word":"Runbook","text":"Pausoz pausoko jarraibideak arazo mota ezagun bat konpontzeko, beti modu berean eta azkar egin dadin. Intzidente handi baten ondoren taldeak bat proposa diezazuke zuk onar dezazun.","also":["runbook-ak","eragiketa-eskuliburua"]},{"id":"ci","g":"run","word":"Konfigurazio-elementua","text":"Zure zerbitzuak behar duen gauza bat, adibidez zerbitzari bat, domeinu bat, ziurtagiri bat, gako bat edo hornitzaile bat. 🗂️ Konfigurazio-elementuak atalak zerbitzuka zerrendatzen ditu, intzidente batek zeri eragiten dion eta zer berritu edo babeskopiatu behar den ikus dezazun.","also":["konfigurazio-elementuak","konfigurazio elementua","CI"]},{"id":"expiry","g":"run","word":"Iraungitze-data","text":"Berritu ezean zerbaitek funtzionatzeari uzten dion data, segurtasun ziurtagiriak edo web helbideak adibidez. AI-gilek datak zaindu eta bakoitza berritzeko txartela 30 egun lehenago sortzen du, ustekabean ezer geldi ez dadin.","also":["iraungitze-datak","iraungitzea","iraungitzeen zaintza"]},{"id":"backup","g":"run","word":"Babeskopia","text":"Zure datuen lehenagoko kopia gorde bat, zerbait galdu edo hondatzen bada erabiltzeko. AI-gile-k zure taulen babeskopia bat egiten du egunero.","also":["babeskopiak","backup"]},{"id":"restore","g":"run","word":"Berreskuratzea","text":"Babeskopia batetik datuak berriro ekartzea. Babeskopia batek benetan balio du berreskura daitekeela dakizunean bakarrik, beraz merezi du noizean behin probatzea.","also":["berreskuratu","berreskuratuta"]},{"id":"svcreview","g":"run","word":"Zerbitzu-berrikuspena","text":"Zerbitzu baten hilabete bati begirada bat atzera: irekitako eta konpondutako intzidenteak, jendeak zein azkar jaso zuen erantzuna, erabilgarritasuna eta erabilitako tokenak. Hileko berrikuspenak zerbitzu bakoitzarena erakusten du.","also":["zerbitzu-berrikuspenak","hileko berrikuspena","hileko berrikuspenak"]},{"id":"accessreview","g":"run","word":"Sarbide-berrikuspena","text":"90 egunean behin oraindik nor sar daitekeen egiaztatzea: partekatze estekak, lagunen rolak eta gordetako pasahitz eta gakoak. Bakoitza mantendu edo kentzen duzu, sarbide zaharrak geratu ez daitezen.","also":["sarbide-berrikuspenak"]},{"id":"improvements","g":"run","word":"Hobekuntza-zerrenda","text":"Taldeak hobetzea erabaki duen guztia, leku bakarrean: retro-iradokizunak, berrikuspen ekintzak eta arazoen konponketak, bakoitza bere egoerarekin. 📈 Hobekuntzak atalean aurkituko duzu.","also":["hobekuntza-zerrendak","hobekuntzak"]},{"id":"tokencap","g":"run","word":"Token muga","text":"Zerbitzu baten agenteek erabil ditzaketen tokenen hileko muga. % 80an abisu bat jasotzen duzu; % 100ean haien atzeko lanak hurrengo hilabetera arte itxaroten du, edo muga igotzen duzun arte.","also":["token mugak","hileko token muga"]},{"id":"svcmgmt","g":"run","word":"Zerbitzuen kudeaketa","text":"Zerbitzua egunero erabilgarri eta martxan mantentzeko behar den guztia, hartaz baliatzen direnentzat.","also":["zerbitzu bat kudeatzea"]},{"id":"itil","g":"run","word":"ITIL","text":"Zerbitzuak ondo kudeatzeko gida oso erabilia, intzidenteak, arazoak eta aldaketak lantzen dituena. Izena IT Infrastructure Library esalditik zetorren."},{"id":"itsm","g":"run","word":"IT zerbitzuen kudeaketa (ITSM)","text":"Teknologia pertsonentzako zerbitzu gisa kudeatzea, eskaerak, intzidenteak, aldaketak eta hobekuntzak lantzeko bide argiekin.","also":["ITSM"]},{"id":"managed","g":"run","word":"Zerbitzu kudeatua","text":"Beste norbaitek zuretzat martxan mantendu eta zaintzen duen zerbitzua, funtzionamenduari buruzko akordio baten arabera.","also":["zerbitzu kudeatuak","managed services"]},{"id":"svcowner","g":"run","word":"Zerbitzuaren arduraduna","text":"Zerbitzu osoaren ardura duen pertsona: nola dabilen, zenbat kostatzen den eta nola hobetzen den.","also":["zerbitzu arduradunak","service owners"]},{"id":"sla","g":"run","word":"Zerbitzu mailaren akordioa (SLA)","text":"Zerbitzua zein ondo ibiliko den bezeroei idatziz emandako hitza, adibidez «denboraren %99,9an martxan» edo «ordubete barru erantzuna», sarritan dirua itzultzeko konpromisoarekin betetzen ez bada.","also":["SLA","SLAs","zerbitzu mailaren akordioa","service level agreement"]},{"id":"slo","g":"run","word":"Zerbitzu mailaren helburua (SLO)","text":"Zerbitzuak aldi batean nola funtzionatu behar duen dioen taldearen helburua, normalean SLA baino zorrotzagoa, segurtasun tartea izateko.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Zerbitzu mailaren adierazlea (SLI)","text":"Helburuarekin alderatzen duzun benetako neurria, ondo kargatu diren bisiten proportzioa adibidez.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Erabilgarritasuna","text":"Jendeak zerbitzua behar duenean erabil dezakeen; sarritan martxan dagoen denboraren bidez neurtzen da.","also":["erabilgarritasun handia","high availability"]},{"id":"downtime","g":"run","word":"Geldialdi denbora","text":"Zerbitzua ez dabilen edo itzalita dagoen denbora, aurreikusita egon ala ez.","also":["geldialdia","down time"]},{"id":"errorbudget","g":"run","word":"Errore aurrekontua","text":"Fidagarritasun helburuak onartzen duen hutsegite kopuru txikia. Tartea geratzen den bitartean aldaketekin arriskatu daiteke; agortzean, moteldu egin behar da.","also":["errore aurrekontuak","error budgets"]},{"id":"outage","g":"run","word":"Zerbitzu etena","text":"Erabiltzaileentzat zerbitzua geldituta edo oso gaizki dagoen aldia.","also":["etenak","outages"]},{"id":"degraded","g":"run","word":"Narriatua","text":"Badabil, baina gaizki: motel edo atal batzuk hondatuta.","also":["zerbitzu narriatua","degraded service"]},{"id":"monitoring","g":"run","word":"Monitorizazioa","text":"Zerbitzua etengabe automatikoki zaintzea, arazoak atzemateko, ahal dela erabiltzaileak ohartu aurretik.","also":["monitorizatua"]},{"id":"observability","g":"run","word":"Behagarritasuna","text":"Erregistro, zenbaki eta aztarnen bidez, kanpotik sistemaren barruan zer gertatzen den zenbateraino jakin dezakezun.","also":["o11y"]},{"id":"log","g":"run","word":"Erregistroa","text":"Programak egiten duenaren egunkaria, zer gaizki joan den argitzeko erabiltzen dena.","also":["erregistroak","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Aztarna","text":"Eskaera batek sistemako ataletan egiten duen bidearen erregistroa, urratsez urrats, non moteldu den erakutsiz.","also":["aztarnak","traces","tracing"]},{"id":"latency","g":"run","word":"Latentzia","text":"Zerbaitek erantzuteko behar duen denbora, klik egin eta orria agertu arteko itxaronaldia adibidez."},{"id":"alert","g":"run","word":"Alerta","text":"Arreta behar duen zerbaiten mezu automatikoa, webguneak erantzuten ez duela adibidez.","also":["alertak","alerting","alerts"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alerta nekea","text":"Hainbeste alerta egotea, non jendea haiei kasurik ez egiten hasten den, garrantzitsuei ere bai.","also":["alarma nekea","alarm fatigue"]},{"id":"dashboard","g":"run","word":"Aginte panela","text":"Zenbaki eta egoera garrantzitsuenak begirada batean erakusten dituen pantaila.","also":["aginte panelak","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Guardiakoari premiaz abisatzea","text":"Arazo bat dela eta guardiakoari premiaz deitzea edo hura esnatzea.","also":["paged"]},{"id":"escalation","g":"run","word":"Goragoko mailara bideratzea","text":"Egungo mailan arazoa konpondu ezin denean edo nahikoa azkar ez doanean, ezagutza edo aginpide handiagoko norbaitengana jotzea.","also":["goragora bideratu","escalate","escalated"]},{"id":"triage","g":"run","word":"Sailkapena","text":"Jasotako arazoak premia eta garrantziaren arabera azkar ordenatzea, larrienak lehenik lantzeko.","also":["sailkatua","triaged"]},{"id":"impact","g":"run","word":"Eragina","text":"Zerbaitek zenbat pertsonari eta zenbateraino eragiten dien.","noTip":1},{"id":"urgency","g":"run","word":"Premia","text":"Zein azkar heldu behar zaion zerbaiti. Eraginak eta premiak batera ezartzen dute lehentasuna.","noTip":1},{"id":"plevels","g":"run","word":"Lehentasun mailak (P1, P2…)","text":"Arazo baten premia adierazteko etiketak. P1 da larriena eta berehalako ekintza behar du.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Tiketen ilara","text":"Norbaitek hartzeko zain dauden eskaera eta intzidenteen zerrenda.","also":["tiketen ilarak","ticket queues"]},{"id":"tiers","g":"run","word":"Lehen eta bigarren maila","text":"Laguntza mailak: lehenak deiak hartu eta arazo errazak konpontzen ditu; bigarrenak zailagoetarako ezagutza sakonagoa du. Tier 1 eta tier 2 ere deitzen zaie.","also":["lehen maila","bigarren maila","lehen mailako laguntza","tier 1","tier 2","first-line support"]},{"id":"ic","g":"run","word":"Intzidentearen koordinatzailea","text":"Intzidente bati emandako erantzuna gidatzen duen pertsona bakarra, denek jakin dezaten nork erabakitzen duen eta nork zer egiten duen.","also":["intzidente koordinatzaileak","incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Erantzun denbora","text":"Norbaitek eskaera edo intzidentea lehen aldiz hartu arteko denbora.","also":["erantzun denborak","response times"]},{"id":"resolution","g":"run","word":"Ebazpen denbora","text":"Eskaera edo intzidentea jakinarazten denetik guztiz konpondu arteko denbora.","also":["ebazpen denborak","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Berreskuratzeko batez besteko denbora (MTTR)","text":"Hondatu ondoren zerbitzua berriro martxan jartzeko batez besteko denbora. MTTRk esanahi desberdinak izan ditzake; argitu zer neurtzen duzun.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Hutsegiteen arteko batez besteko denbora (MTBF)","text":"Zerbait hondatu aurretik zerbitzuak batez beste martxan irauten duen denbora.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Konfigurazioa kudeatzeko datu basea (CMDB)","text":"Konfigurazio elementuen eta haien arteko loturen zerrenda, zer zeren mende dagoen ikusteko.","also":["CMDB"]},{"id":"asset","g":"run","word":"Aktiboa","text":"Zerbitzua martxan mantentzeko daukazun edo ordaintzen duzun baliozko edozer, eramangarri bat, lizentzia edo domeinua adibidez.","also":["aktiboak","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Edukiera planifikatzea","text":"Etorriko denerako nahikoa konputazio indar, biltegiratze eta pertsona egongo direla ziurtatzea.","also":["edukiera plana","capacity plan"]},{"id":"scaling","g":"run","word":"Eskalatzea","text":"Erabiltzaile gehiagori erantzutea, makina bati indar gehiago emanez (scaling up) edo makina gehiago gehituz (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Negozioaren jarraitutasuna","text":"Zerbait larria gertatzean gauza garrantzitsuak martxan mantentzeko planak, bulegoa, hornitzaile nagusia edo ordenagailuak galtzean adibidez.","also":["negozioaren jarraitutasun plana","business continuity plan"]},{"id":"dr","g":"run","word":"Hondamendien ondoko berreskuratzea (DR)","text":"Gertaera larri baten ondoren zerbitzua berreskuratzeko plana eta tresnak, datu zentro osoa galtzean adibidez.","also":["hondamendien ondoko berreskuratzea","disaster recovery"]},{"id":"rto","g":"run","word":"Berreskuratze denboraren helburua (RTO)","text":"Hondamendi baten ondoren zerbitzua gehienez zenbat denboraz egon daitekeen geldirik.","also":["RTO"]},{"id":"rpo","g":"run","word":"Berreskuratze puntuaren helburua (RPO)","text":"Denboran neurtuta, azken datuetatik zenbat gal dezakezun. Ordubeteko RPOk gutxienez orduro babeskopiak egitea eskatzen du.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Erredundantzia","text":"Ordezkoak prest edukitzea, bigarren zerbitzari bat adibidez, hutsegite bakar batek zerbitzua gelditu ez dezan.","also":["erredundantea"]},{"id":"failover","g":"run","word":"Hutsegiteko ordezkapena","text":"Ohiko sistemak huts egitean ordezko sistemara automatikoki pasatzea.","also":["fail over"]},{"id":"spof","g":"run","word":"Hutsegite puntu bakarra","text":"Hondatzean sistema osoa gelditzen duen atal bakarra, ordezkorik ez duelako.","also":["hutsegite puntu bakarrak","SPOF","single points of failure"]},{"id":"maintwin","g":"run","word":"Mantentze tartea","text":"Erabiltzaileei aurrez jakinarazitako aldia, mantentze lanengatik zerbitzua geldi edo motel egon daitekeena.","also":["mantentze tarteak","programatutako mantentzea","planned maintenance","maintenance windows"]},{"id":"handover","g":"run","word":"Eskualdatzea","text":"Lana, ezagutza eta ardura beste pertsona edo talde bati pasatzea, ezer ahaztuta geratu ez dadin.","also":["eskualdatzeak","handovers"]},{"id":"kb","g":"run","word":"Ezagutza basea","text":"Erabiltzaileentzako eta taldearentzako laguntza artikulu eta erantzunen bilduma.","also":["ezagutza baseak","knowledge bases"]},{"id":"csat","g":"run","word":"Bezeroaren gogobetetzea (CSAT)","text":"Erabiltzaileek zein pozik dauden adierazteko ematen duten puntuazioa, sarritan eskaera ixtean galdetua.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Hornitzailea","text":"Behar duzun kanpoko enpresa, ostatu hornitzailea adibidez. Hirugarrena ere esaten zaio.","also":["hornitzaileak","vendor","vendors","hirugarrena","third party","suppliers"],"noTip":1},{"id":"retire","g":"run","word":"Zerbitzua erretiratzea","text":"Zerbitzua behin betiko segurtasunez itzaltzea: erabiltzaileei abisatu, datuak eta sarbideak kudeatu eta kostuak etetea.","also":["zerbitzu bat erretiratzea","retiring a service"]},{"id":"eol","g":"run","word":"Bizitza erabilgarriaren amaiera (EOL)","text":"Fabrikatzaileak produktuari eguneratzeak edo laguntza emateari uzten dionean; ordezkatzea komeni da.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Zibersegurtasuna","text":"Sistemak eta datuak sartze baimengabeetatik, lapurretetatik eta kalteetatik babestea.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Autentifikazioa","text":"Norbait nor den egiaztatzea, normalean pasahitz edo kode batekin. Authn laburdura erabiltzen da maiz.","also":["authn"]},{"id":"authz","g":"sec","word":"Baimena egiaztatzea","text":"Norbait nor den jakinda, zer egin dezakeen egiaztatzea. Authz laburdura erabiltzen da maiz.","also":["authz","authorization","autorizazioa"]},{"id":"mfa","g":"sec","word":"Faktore anitzeko autentifikazioa (MFA)","text":"Bi froga edo gehiagorekin saioa hastea, pasahitza eta telefonoko kodea adibidez. Bi direnean, bi faktorekoa (2FA) esaten zaio.","also":["MFA","2FA","bi faktore","bi faktoreko autentifikazioa","two-factor authentication","two-factor"]},{"id":"sso","g":"sec","word":"Saio hasiera bakarra (SSO)","text":"Behin saioa hasita sistema askotan sartzea, laneko kontua nonahi erabiltzea adibidez.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Pasahitz kudeatzailea","text":"Pasahitz sendoak sortu eta zure ordez gogoratzen dituen aplikazioa.","also":["pasahitz kudeatzaileak","password managers"]},{"id":"secret","g":"sec","word":"Sekretua","text":"Programak nonbait sartzeko erabiltzen duen pasahitz, gako edo kode pribatua. Ez da partekatu edo kodean idatzi behar.","also":["sekretuak","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API gakoa","text":"Beste zerbitzu baten APIa erabiltzeko kode sekretua, nork erabiltzen eta ordaintzen duen erakusten duena.","also":["API gakoak","API keys"]},{"id":"accesstoken","g":"sec","word":"Sarbide tokena","text":"Programak sartzeko baimena duela frogatzen duen aldi baterako txartela, aldi bakoitzean pasahitza behar ez izateko. Ez da AI token baten gauza bera.","also":["sarbide tokenak","access tokens"]},{"id":"encryption","g":"sec","word":"Zifratzea","text":"Informazioa nahastea, gako egokia duenak bakarrik irakurri ahal izateko.","also":["zifratua","zifratu","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"Web orriak bidaltzeko modu segurua, nabigatzaileko giltzarrapoak adierazia, tarteko inork irakurri edo aldatu ez ditzan."},{"id":"cert","g":"sec","word":"SSL/TLS ziurtagiria","text":"Webguneak nor den frogatu eta HTTPS erabiltzeko duen nortasun agiri digitala. Iraungitzen denez, berritu egin behar da.","also":["TLS ziurtagiria","SSL ziurtagiria","ziurtagiria","ziurtagiriak","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Baimenak","text":"Nork zer ikusi edo aldatu dezakeen ezartzen duten arauak.","also":["baimena","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Gutxieneko pribilegioa","text":"Pertsona edo programa bakoitzari benetan behar duen sarbidea soilik ematea, behar duen denboran soilik.","also":["gutxieneko pribilegioaren printzipioa","principle of least privilege"]},{"id":"rbac","g":"sec","word":"Roletan oinarritutako sarbide kontrola (RBAC)","text":"Sarbidea rolaren arabera ematea, irakurlea edo editorea adibidez, pertsonaz pertsona eman beharrean.","also":["RBAC","roletan oinarritutako sarbidea","role-based access"]},{"id":"vuln","g":"sec","word":"Ahultasuna","text":"Norbaitek sartzeko edo kalte egiteko erabil lezakeen puntu ahula.","also":["ahultasunak","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero eguneko ahultasuna","text":"Sortzaileek konpontzeko astirik izan aurretik erasotzaileek ezagutzen duten ahultasuna.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malwarea","text":"Kalte egiteko, zelatatzeko edo lapurtzeko sortutako software gaiztoa, birusak adibidez."},{"id":"ransomware","g":"sec","word":"Ransomwarea","text":"Fitxategiak blokeatu eta desblokeatzeko dirua eskatzen duen malwarea. Babeskopia onak dira defentsarik onena.","also":["ransomware erasoa","ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishinga","text":"Pasahitzak edo dirua emateko, edo zerbait kaltegarria irekitzeko engainatzen saiatzen diren mezu faltsuak.","also":["phishing mezua","phishing mezuak","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Ingeniaritza soziala","text":"Ordenagailuen ordez pertsonak engainatzea sarbidea lortzeko, «laguntza informatikoaren» dei faltsu batekin adibidez."},{"id":"firewall","g":"sec","word":"Suebakia","text":"Sareko zer trafiko sartu edo atera daitekeen erabakitzen duen zaindaria.","also":["suebakiak","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Internet bidezko lotura pribatu zifratua, sarritan laneko sistemetara segurtasunez sartzeko erabiltzen dena.","also":["sare pribatu birtuala","virtual private network"]},{"id":"ddos","g":"sec","word":"Zerbitzu ukapena (DoS, DDoS)","text":"Zerbitzua trafiko faltsuz betetzea benetako jendeak erabili ezin izan arte. DDoS bada, ordenagailu askotatik dator aldi berean.","also":["DoS","DDoS","zerbitzu ukapena","DDoS erasoa","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Sartze proba","text":"Konfiantzazko adituei sartzen saiatzeko eskatzea, benetako erasotzaileen aurretik ahultasunak aurkitzeko.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Segurtasun auditoria","text":"Zerbait zein ondo babestuta dagoen arretaz egiaztatzea, jardunbide onen zerrenda batekin alderatuz.","also":["segurtasun auditoriak","security audits"]},{"id":"threatmodel","g":"sec","word":"Mehatxuen modelatzea","text":"Nork eraso lezakeen, nola eta geldiarazteko zer egingo zenukeen pentsatzea.","also":["mehatxu eredua","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Datu urraketa","text":"Informazio pribatua eduki behar ez lukeenarengana iristea, edo baimenik gabe galtzea edo aldatzea.","also":["datu urraketak","data breaches"]},{"id":"pii","g":"sec","word":"Datu pertsonalak","text":"Identifika daitekeen pertsona bati buruzko informazioa, izena, posta helbidea edo kokapena adibidez. PII ere esaten zaio.","also":["PII","pertsona identifikatzeko informazioa","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"DBEO","text":"Datu pertsonalei buruzko Europako araua; Erresuma Batuak bere bertsioa du. Beharrezkoa soilik bildu, seguru gorde eta pertsonei beren datuak ikusten edo ezabatzen utzi behar zaie.","also":["GDPR","Datuak Babesteko Erregelamendu Orokorra","General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Datu babesa","text":"Datu pertsonalak behar bezala eta legearen barruan zaintzea.","also":["datuak babesteko legea","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Pribatutasun politika","text":"Zer datu pertsonal biltzen dituzun, zergatik eta haiekin zer egiten duzun azaltzen duen orri publikoa.","also":["pribatutasun adierazpena","pribatutasun oharra","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Adostasuna","text":"Pertsonak bere datuak modu jakin batean erabiltzeko askatasunez eta argi emandako baietza. Edonoiz ken dezake.","also":["berariazko onarpena","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookiea","text":"Webguneak nabigatzailean zerbait gogoratzeko gordetzen duen fitxategi txikia, saioa hasita dagoela adibidez. Batzuek aurretiko adostasuna behar dute.","also":["cookieak","cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Datuen minimizazioa","text":"Lanerako benetan behar diren datu pertsonalak soilik bildu eta gordetzea.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Datuak gordetzea","text":"Datuak ezabatu aurretik zenbat denboraz gordetzen diren. Behar baino gehiago ez gordetzea seguruagoa da eta sarritan legeak eskatzen du.","also":["gordetze epea","retention period"]},{"id":"anon","g":"sec","word":"Anonimizazioa","text":"Datuak aldatzea, haietatik inor zentzuzko bideekin identifikatu ezin izateko.","also":["anonimizatua","anonymization","datu anonimoak","anonymous data","anonymised"]},{"id":"pseudo","g":"sec","word":"Pseudonimizazioa","text":"Izenak eta beste xehetasunak kodez ordezkatzea, atzera lotzeko gakoa aparte gordeta. Datu pertsonalak izaten jarraitzen dute.","also":["pseudonimizatua","pseudonymization","pseudonymised"]},{"id":"dpa","g":"sec","word":"Datu tratamenduaren akordioa (DPA)","text":"Hornitzaileak zure izenean datu pertsonalak nola trata ditzakeen ezartzen duen kontratua.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Datu babesaren gaineko eraginaren ebaluazioa (DPIA)","text":"Hasi aurretik, datu pertsonalak erabiltzeko planak pertsonei nola eragin diezaiekeen eta arriskuak nola gutxitu arretaz aztertzea.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Auditoria erregistroa","text":"Nork zer eta noiz egin duen jasotzen duen erregistroa, gero ekintzak egiaztatzeko.","also":["auditoria erregistroak","auditoria arrastoa","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Araudia betetzea","text":"Dagozkizun lege, arau eta estandarrak betetzea eta frogatu ahal izatea.","also":["araudia betetzen duena","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Informazioaren segurtasuna kudeatzeko nazioarteko estandar ezaguna. Enpresek betetzen dutela ziurtatzen duen agiria lor dezakete.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Kanpoko auditoreek egiaztatutako AEBetako txostena, enpresak bezeroen datuak behar bezala zaintzen dituela erakusten duena.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agente","text":"Zeregin batean bere kabuz lan egiten duen AI: kodea irakurri, aldaketak egin, egiaztapenak exekutatu eta emaitzak jakinarazten ditu. Haren lana ere egiaztatzen da.","also":["agenteak"]},{"id":"token","g":"ai","word":"Token","text":"AIak irakurri eta idazten dituen testu zati txikiak, bakoitza hitz baten hiru laurden ingurukoa. Erabilera tokenetan zenbatzen da; gutxiago gastatuta, zure planeko erabilera tarte handiagoa geratzen zaizu.","also":["token-ak","tokenak"]},{"id":"hook","g":"ai","word":"Hook","text":"Une jakin batean bere kabuz exekutatzen den komando txikia, AI saioa hastean adibidez, taldeak zure iruzkinak jaso ditzan.","also":["hook-ak","hookak"]},{"id":"ai","g":"ai","word":"Adimen artifiziala (AI)","text":"Normalean pertsonen lana dela uste duguna egiten duten sistema informatikoak, idaztea, galderei erantzutea edo irudiak ezagutzea adibidez.","also":["AI","AA","adimen artifiziala","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Ikaskuntza automatikoa (ML)","text":"Ordenagailuei adibide askotatik patroiak ikasarazteko modua, arau zehatzak eman beharrean.","also":["ikaskuntza automatikoa","machine learning"]},{"id":"model","g":"ai","word":"Eredua","text":"AI sistema baten «garun» trebatua, adibide askotatik ikasia. Ereduek gaitasun, abiadura eta prezio desberdinak dituzte.","also":["ereduak","modeloa","AI eredua","AI model","model","models"],"noTip":1},{"id":"llm","g":"ai","word":"Hizkuntza eredu handia (LLM)","text":"Testu kopuru izugarriekin trebatutako AI eredua, hizkuntza irakurri eta idazteko.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"AI sortzailea","text":"Gauza berriak sortzen dituen AI, testuak, irudiak edo kodea adibidez, sailkatu edo atzeman soilik egin beharrean.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Txatbota","text":"Eguneroko hizkuntzan, idatziz edo ahoz, hitz egiteko programa.","also":["txatbotak","chatbots"]},{"id":"prompt","g":"ai","word":"Prompt-a","text":"AIari ematen diozuna: galdera edo argibideak eta erantsitako guztia. Zenbat eta argiago, orduan eta erantzun hobea normalean.","also":["argibideak","prompts"]},{"id":"prompteng","g":"ai","word":"Prompt ingeniaritza","text":"Emaitza fidagarri eta erabilgarriak ematen dituzten argibideak idazteko trebetasuna.","also":["argibideak idaztea"]},{"id":"sysprompt","g":"ai","word":"Sistemaren argibideak","text":"Elkarrizketa hasi aurretik AIaren eginkizuna eta arauak ezartzen dituzten argibideak. Zuk idatzitakoak baino pisu handiagoa dute.","also":["system prompts","sistemaren argibidea","sistemaren argibideak","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Testuingurua","text":"AIak lanean ari dela ikus dezakeen guztia: argibideak, zure mezuak, irakurritako fitxategiak eta aurreko erantzunak.","noTip":1},{"id":"ctxwin","g":"ai","word":"Testuinguru leihoa","text":"AIak aldi berean gogoan eduki dezakeena, tokenetan neurtuta. Muga gainditzean, zati zaharrak kendu edo laburbiltzen dira.","also":["testuinguru leihoak","context windows"]},{"id":"session","g":"ai","word":"Saioa","text":"AI batekin hasieratik amaierara izandako lan elkarrizketa. Saio berria oroimen hutsez hasten da.","also":["saioak","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Oroimena","text":"AIak saioen artean gordetzen dituen oharrak, zure hobespenak eta aurreko erabakiak gogoratzeko.","noTip":1},{"id":"hallucination","g":"ai","word":"Haluzinazioa","text":"AIak segurtasunez esaten duen zerbait asmatua edo okerra denean. Egiaztatu gertaera garrantzitsuak.","also":["haluzinazioak","asmatu","hallucinate","hallucinates","hallucinations"]},{"id":"training","g":"ai","word":"Trebakuntza","text":"Inork erabili aurretik ereduari adibide askoren bidez irakastea.","also":["trebatua","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Trebakuntza datuak","text":"Ereduak ikasteko erabilitako adibideak. Haren ezagutza datu horiek bildu ziren datan amaitzen da.","also":["trebakuntza multzoa","training set"]},{"id":"cutoff","g":"ai","word":"Ezagutzaren azken data","text":"AIaren barneko ezagutza amaitzen den data. Geroagoko gauzak ez ditu jakingo, bilatzen ez baditu.","also":["trebakuntzaren azken data","training cutoff"]},{"id":"finetune","g":"ai","word":"Doikuntza fina","text":"Lehendik dagoen eredua zure adibideekin gehiago trebatzea, lan jakin batean hobetzeko.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inferentzia","text":"AI eredua erantzuteko erabiltzea, trebatu beharrean.","also":["ereduaren inferentzia","model inference"]},{"id":"tooluse","g":"ai","word":"Tresnak erabiltzea","text":"AIak hitz egiteaz gain gauzak egin ahal izatea: komandoak exekutatu, fitxategiak irakurri edo sarean bilatu, aplikazioak emandako tresnekin.","also":["tresnei deitzea","tresna deia","tresna deiak","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Azpiagentea","text":"AI nagusiak lan txikiago bat egiteko erabiltzen duen AI laguntzailea, emaitza itzultzen diona.","also":["azpiagenteak","sub-agent","subagents"]},{"id":"multiagent","g":"ai","word":"Agente anitzekoa","text":"Lan berean elkarrekin ari diren hainbat AI, bakoitza bere zatiarekin, talde txiki bat bezala.","also":["agente anitzeko sistema","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomia","text":"AIak pertsona bati galdetu aurretik bere kabuz zenbat egin dezakeen.","also":["autonomoa","autonomous"]},{"id":"hitl","g":"ai","word":"Gizakia tartean","text":"Une garrantzitsuetan AIak egiten duena egiaztatu edo onartzeko pertsona bat tartean mantentzea. AI-gilen zu zara.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Babes mugak","text":"AIaren ekintzak seguruago egiten dituzten mugak eta egiaztapenak, argitaratu aurretik onarpena eskatzea adibidez. Akatsen arriskua gutxitzen dute, baina ez dute desagerrarazten.","also":["babes muga","guardrail"]},{"id":"rag","g":"ai","word":"Berreskuratze bidez osatutako sorkuntza (RAG)","text":"Erantzun aurretik AIari zure dokumentuetan bilatzen uztea, zure datuetan oinarritu dadin.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Zenbakizko adierazpena","text":"Testua haren esanahia jasotzen duen zenbaki zerrenda bihurtzea, ordenagailuak antzeko esanahiko gauzak aurkitzeko.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Datu base bektoriala","text":"Zenbaki zerrenda horietan bilatu eta antzeko esanahia duen materiala aurkitzeko prestatutako datu basea.","also":["datu base bektorialak","biltegi bektoriala","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Tresnak eta datu iturriak AI aplikazioetara lotzeko modu bateratua, AIak erabili ahal izateko.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Tenperatura","text":"Erantzunak zein ausartak diren ezartzen du: balio baxuak erantzun egonkorragoak ematen ditu, eta altuak askotarikoagoak. Ez batak ez besteak ez du beti asmatzea bermatzen.","also":["ereduaren tenperatura","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodala","text":"Informazio mota bat baino gehiagorekin lan egiteko gai dena, testua, irudiak eta soinua adibidez.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Ebaluazioa (eval)","text":"Aukeratutako adibideetan AIak nola egiten duen neurtzeko proba planifikatua, ereduak edo argibideak alderatzeko.","also":["eval","evals","ebaluazioak"]},{"id":"bias","g":"ai","word":"Alborapena","text":"AI edo pertsona batek alde batera bidegabe jotzea, sarritan ikasitakoagatik.","also":["alboratua","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"AI arduratsua","text":"AI modu bidezko, seguru eta zintzoan erabiltzea, emaitzen erantzule pertsonak izaten jarraituta.","also":["AI etikoa","ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injekzioa","text":"Web orri edo fitxategiko ezkutuko argibideen bidez, AIari erabiltzaileak eskatu ez duen zerbait eginarazteko trikimailua.","also":["prompt injekzioak","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Eskaera maiztasunaren muga","text":"Denbora jakin batean zerbitzuari bidal diezazkiokezun eskaeren muga. Gaindituz gero, itxaron behar duzu.","also":["eskaera mugak","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Erabilera muga","text":"Zure planak aldi batean onartzen duen AI lana; hortik aurrera gelditu edo gehiago kostatzen da.","also":["erabilera mugak","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Softwarea batez ere AIari zer nahi duzun azalduz eta kodea hari idazten utziz sortzea.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Aurrekontua","text":"Zerbaitetarako gordetako diru kopurua.","also":["aurrekontuak","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Kostuen zenbatespena","text":"Hasi aurretik zerbaitek zenbat kostatuko duen kalkulatzea.","also":["kostuen zenbatespenak","cost estimates"]},{"id":"roi","g":"money","word":"Inbertsioaren errentagarritasuna (ROI)","text":"Jarritakoarekin alderatuta jasotzen duzuna. Positiboa bada, merezi izan du.","also":["ROI"]},{"id":"tco","g":"money","word":"Jabetzaren kostu osoa (TCO)","text":"Zerbaiten bizitza osoko benetako kostua, erosketa prezioaz gain: funtzionamendua, laguntza, eguneratzeak eta azken erretiratzea.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx eta OpEx","text":"CapEx gordeko dituzun gauzetan hasieran gastatutako dirua da; OpEx etengabeko gastuak dira, hileko fakturak adibidez.","also":["CapEx","OpEx","kapital gastuak","ustiapen gastuak","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Harpidetza","text":"Zerbait erabiltzen jarraitzeko aldizka ordaintzea, normalean hilero edo urtero.","also":["harpidetzak","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Softwarea zerbitzu gisa (SaaS)","text":"Sarean erabili eta harpidetzaz ordaintzen duzun softwarea, sortzaileak zure ordez martxan mantentzen duena.","also":["SaaS"]},{"id":"payg","g":"money","word":"Erabileraren araberako ordainketa","text":"Erabiltzen duzunagatik soilik ordaintzea, hodeiko baliabideak edo AI tokenak adibidez.","also":["pay-as-you-go","erabileraren araberako prezioak","usage-based pricing"]},{"id":"overage","g":"money","word":"Gehiegizko erabilera","text":"Zure planak barne hartzen duena gainditzen duen erabilera; gehiago kosta daiteke.","also":["gehiegizko erabilerak","gainditze karguak","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Gastu alerta","text":"Gastua edo erabilera aukeratutako mailara iristean jasotzen duzun mezua. Abisatzen du, baina ez ditu beti hurrengo karguak gelditzen.","also":["gastu alertak","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Doako plana","text":"Ordainpeko zerbitzu baten doako maila, mugekin. Hasteko erabilgarria da.","also":["free plan"]},{"id":"pricing","g":"money","word":"Prezio plana","text":"Zerbitzuak saltzen dituen paketeak, bakoitza bere prezio eta mugekin.","also":["prezio planak","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Lizentzia","text":"Beste norbaitek sortutakoa erabili, kopiatu, aldatu edo partekatzeko arauak, softwarea, letra tipoak edo irudiak adibidez.","also":["lizentziak","license","licenses","licences"],"noTip":1},{"id":"opensource","g":"money","word":"Kode irekia","text":"Edonork irakurri, erabili eta sarritan doan alda dezakeen kodea duen softwarea, lizentziaren arauen arabera.","also":["open-source","kode irekiko softwarea","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Kode irekiko lizentzia","text":"Kode irekiak dakartzan arauak. Batzuek ia dena onartzen dute, MITek bezala; besteek zure aldaketak ere partekatzeko eskatzen dute, GPLk bezala.","also":["kode irekiko lizentziak","MIT lizentzia","GPL","open source licences","MIT licence"]},{"id":"proprietary","g":"money","word":"Jabeduna","text":"Enpresa batena dena, libreki kopiatu edo aldatu ezin dena. Kode irekiaren aurkakoa.","also":["software jabeduna","proprietary software"]},{"id":"copyright","g":"money","word":"Egile eskubideak","text":"Sortzaileak bere lanaren kopiak kontrolatzeko duen legezko eskubidea, kodea eta idazkiak barne.","also":["egile eskubideek babestua","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Jabetza intelektuala (IP)","text":"Legeak jabetzatzat hartzen dituen ideiak eta sorkuntzak, kodea, diseinuak, izenak eta logotipoak adibidez.","also":["jabetza intelektuala","intellectual property"]},{"id":"tos","g":"money","word":"Zerbitzu baldintzak","text":"Zerbitzu bat erabiltzean onartzen dituzun arauak.","also":["baldintzak","erabilera baldintzak","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Kontratua","text":"Bi alderen arteko idatzizko akordioa, legez bete beharrekoa.","also":["kontratuak","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Lanaren zehaztapena (SOW)","text":"Zer lan egingo den, noizko eta zenbat diruren truke zehazten duen dokumentua.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Prezio finkoa","text":"Lan osoarentzat adostutako prezioa, zenbat denbora behar den gorabehera.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Denbora eta materialak","text":"Benetan lan egindako orduak eta erabilitako gauzak ordaintzea, prezio finko baten ordez.","also":["T&M"]},{"id":"invoice","g":"money","word":"Faktura","text":"Egindako lana edo emandako ondasunak ordaintzeko eskatzen duen agiria.","also":["fakturak","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Hornitzailearekiko lotura","text":"Hornitzailea aldatzea hain zaila edo garestia izatea, non harekin harrapatuta geratzen zaren.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Erosketa prozesua","text":"Hornitzaileak aukeratu eta haiei erosteko prozesua.","also":["erosketak"]},{"id":"servicecredit","g":"money","word":"Zerbitzu konpentsazioa","text":"Hornitzaileak SLA betetzen ez duenean jasotzen duzun diru itzulketa edo deskontua.","also":["zerbitzu konpentsazioak","service credits"]}]}};
